export const ALL_WORK: WorkItem[] = [...APPROVALS, ...NOTICES];
export type WorkDecisions = Partial<Record<string, WorkStatus>>;
export const WORK_STORAGE_KEY = 'orbita-rebuild-demo-work-v1';
export const categoryOptions = ['全部', '商品', '订单', '活动与广告', '经营'] as const;
export type CategoryFilter = typeof categoryOptions[number];

export function readWorkDecisions(): WorkDecisions {
  try {
    const raw = JSON.parse(localStorage.getItem(WORK_STORAGE_KEY) || '{}') as Record<string,unknown>;
    const result: WorkDecisions = {};
    for (const item of ALL_WORK) {
      if (['verified','dismissed','seen'].includes(String(raw[item.id])))
        result[item.id] = raw[item.id] as WorkStatus;
    }
    return result;
  } catch { return {}; }
}
export function writeWorkDecisions(next: WorkDecisions) {
  try { localStorage.setItem(WORK_STORAGE_KEY, JSON.stringify(next)); }
  catch { /* Keep the current tab usable when storage is unavailable. */ }
}
export function workStatus(item: WorkItem, decisions: WorkDecisions): WorkStatus {
  return decisions[item.id] || 'pending';
}
export function workTab(item: WorkItem, decisions: WorkDecisions): WorkTab {
  if (workStatus(item, decisions) !== 'pending') return 'processed';
  return item.kind === 'approval' ? 'pending' : item.tab;
}
export function countWorkTab(tab: WorkTab, decisions: WorkDecisions) {
  return ALL_WORK.filter(item => workTab(item, decisions) === tab).length;
}
