import * as React from 'react';
import { cva, type VariantProps } from 'class-variance-authority';
import { twMerge } from 'tailwind-merge';
import clsx from 'clsx';
import * as Tooltip from '@radix-ui/react-tooltip';

const buttonVariants = cva('ui-button', {
  variants: {
    variant: { primary:'ui-primary', secondary:'ui-secondary', ghost:'ui-ghost', outline:'ui-outline' },
    size: { sm:'ui-sm', md:'ui-md', lg:'ui-lg', icon:'ui-icon' },
  },
  defaultVariants: { variant:'ghost', size:'md' },
});
export const cn = (...args: Parameters<typeof clsx>) => twMerge(clsx(...args));
export type ButtonProps = React.ButtonHTMLAttributes<HTMLButtonElement> & VariantProps<typeof buttonVariants>;
export const Button = React.forwardRef<HTMLButtonElement,ButtonProps>(
  ({ variant, size, className, type='button', ...props },ref)=><button type={type} ref={ref} className={cn(buttonVariants({variant,size}),className)} {...props}/>
);
Button.displayName='Button';
export const IconButton = React.forwardRef<HTMLButtonElement,ButtonProps>(
  ({ size='icon', ...rest },ref)=><Button ref={ref} size={size} variant="ghost" {...rest}/>
);
IconButton.displayName='IconButton';
export const TextInput = React.forwardRef<HTMLInputElement,React.InputHTMLAttributes<HTMLInputElement>>(
  ({className,...rest},ref)=><input ref={ref} className={cn('ui-input',className)} {...rest}/>
);
TextInput.displayName='TextInput';
export const Textarea = React.forwardRef<HTMLTextAreaElement,React.TextareaHTMLAttributes<HTMLTextAreaElement>>(
  ({className,...rest},ref)=><textarea ref={ref} className={cn('ui-textarea',className)} {...rest}/>
);
Textarea.displayName='Textarea';
export const Card = ({className,...props}:React.HTMLAttributes<HTMLDivElement>)=><div className={cn('ui-card',className)} {...props}/>;
export const Badge = ({className,...props}:React.HTMLAttributes<HTMLSpanElement>)=><span className={cn('ui-badge',className)} {...props}/>;
export function Avatar({ name }: {name:string}){return <span className="ui-avatar" aria-label={name}>{name.slice(0,1).toUpperCase()}</span>}
export function ToolButton({label,children,onClick}: {label:string;children:React.ReactNode;onClick?:()=>void}){
  return <Tooltip.Root><Tooltip.Trigger asChild><IconButton aria-label={label} onClick={onClick}>{children}</IconButton></Tooltip.Trigger><Tooltip.Portal><Tooltip.Content side="right" sideOffset={8} className="ui-tooltip">{label}</Tooltip.Content></Tooltip.Portal></Tooltip.Root>;
}
