import {useEffect,useRef,useState} from 'react';
import {ArrowUp,Expand,MessageCircle,Paperclip,X} from 'lucide-react';
import {makeChatExchange,validateAttachment,CHAT_MAX_TEXT,type ChatAttachment,type ChatMessage} from '../domain/chat';

type Session={draft:string;messages:ChatMessage[];files?:ChatAttachment[]};
const KEY='orbita-business-assistant-v5';
function readSessions():Record<string,Session>{
  try{const value=JSON.parse(localStorage.getItem(KEY)||'{}');return value&&typeof value==='object'&&!Array.isArray(value)?value:{};}catch{return {}}
}
const contextLabel=(path:string)=>path.startsWith('/products')?'商品':path.startsWith('/orders')?'订单':path.startsWith('/todo')?'待处理':path.startsWith('/growth')?'经营增长':path.startsWith('/strategy')?'经营策略':path.startsWith('/new-product')?'上新':'工作台';
export default function BusinessAssistant({route,onFullChat}:{route:string;onFullChat:(question:string)=>void}){
  const context=route.split('?')[0];
  const [sessions,setSessions]=useState<Record<string,Session>>(readSessions);
  const [open,setOpen]=useState(false);
  const input=useRef<HTMLTextAreaElement>(null);
  const fileInput=useRef<HTMLInputElement>(null);
  const [error,setError]=useState('');
  const panel=useRef<HTMLDivElement>(null);
  const current=sessions[context]||{draft:'',messages:[]};
  const messages=Array.isArray(current.messages)?current.messages:[];
  const draft=typeof current.draft==='string'?current.draft:'';
  const files=Array.isArray(current.files)?current.files:[];
  useEffect(()=>{const field=input.current;if(!field)return;field.style.height='25px';field.style.height=Math.min(85,Math.max(25,field.scrollHeight))+'px'},[draft,context]);
  useEffect(()=>{try{localStorage.setItem(KEY,JSON.stringify(sessions))}catch{/* storage can be unavailable */}},[sessions]);
  useEffect(()=>setOpen(false),[context]);
  useEffect(()=>{if(open)panel.current?.scrollTo({top:panel.current.scrollHeight})},[open,messages.length]);
  useEffect(()=>{const handler=(e:KeyboardEvent)=>{if(e.key==='Escape'&&open){setOpen(false);input.current?.focus()}};window.addEventListener('keydown',handler);return()=>window.removeEventListener('keydown',handler)},[open]);
  useEffect(()=>{if(!open)return;const observer=new MutationObserver(()=>{
    if(document.querySelector('.product-panel[role="dialog"],.v4-detail-drawer[role="dialog"],.v4-detail-drawer[aria-modal="true"]'))setOpen(false);
  });observer.observe(document.body,{childList:true,subtree:true});return()=>observer.disconnect()},[open]);
  const update=(value:Session)=>setSessions(old=>({...old,[context]:value}));
  function chooseFiles(list:FileList|null){
    if(!list)return;
    const chosen=Array.from(list);
    const invalid=chosen.map(validateAttachment).find(Boolean);
    if(invalid){setError(invalid);return}
    if(files.length+chosen.length>8){setError('最多添加 8 个文件');return}
    setError('');update({draft,messages,files:[...files,...chosen.map(f=>({name:f.name,size:f.size,type:f.type}))]});
  }
  function send(){
    const question=draft.trim();if(!question&&!files.length)return;
    update({draft:'',files:[],messages:[...messages,...makeChatExchange(`[${contextLabel(context)}页面] ${question}`,files)].slice(-40)});
    setOpen(true);
  }
  return <section className="business-assistant assistant-compact" aria-label="全局 Orbita 助手">
    {open&&<div className="business-assistant-conversation" aria-label="页面内 AI 会话">
      <div className="business-assistant-heading"><strong><MessageCircle size={16}/> Orbita · {contextLabel(context)}</strong>
        <button onClick={()=>onFullChat(messages.filter(m=>m.role==='user').at(-1)?.text.replace(/^\[[^\]]+\]\s*/,'')||'')} aria-label="进入完整对话"><Expand size={16}/></button>
        <button onClick={()=>{setOpen(false);input.current?.focus()}} aria-label="收起 AI 会话"><X size={16}/></button></div>
      <div className="business-assistant-messages" ref={panel} role="log" aria-live="polite">
        {messages.map(m=><div key={m.id} className={'business-assistant-message '+m.role}>
          <small>{m.role==='assistant'?'Orbita · 本地演示':'你'}</small><p>{m.text}</p>
          {m.proposal&&<p>操作预览：{m.proposal.sku} · {m.proposal.before} → {m.proposal.after}（仅演示，不执行）</p>}
        </div>)}
      </div>
    </div>}
    <form className="business-assistant-form" onSubmit={e=>{e.preventDefault();send()}}>
      {files.length>0&&<div className="chat-selected-files">{files.map((f,i)=><span className="chat-file" key={f.name+i}>{f.name}<button type="button" aria-label={'移除 '+f.name} onClick={()=>update({draft,messages,files:files.filter((_,j)=>j!==i)})}><X size={14}/></button></span>)}</div>}
      <div className="business-assistant-editor"><textarea ref={input} aria-label={'在'+contextLabel(context)+'页面问 Orbita'} placeholder="描述你的经营问题或任务…" rows={1} maxLength={CHAT_MAX_TEXT} value={draft}
        onChange={e=>update({draft:e.target.value,messages,files})} onKeyDown={e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.nativeEvent.isComposing){e.preventDefault();send()}}}/></div>
      <div className="chat-composer-actions">
        <input ref={fileInput} type="file" hidden multiple accept="image/png,image/jpeg,image/webp,image/gif,.png,.jpg,.jpeg,.webp,.gif,.xlsx,.xls,.json" onChange={e=>{chooseFiles(e.currentTarget.files);e.currentTarget.value=''}}/>
        <button type="button" className="business-assistant-attach" aria-label="添加图片或表格" title="仅保留文件名，不读取或上传内容" onClick={()=>fileInput.current?.click()}><Paperclip size={20}/></button>
        <span className="chat-composer-limit">{draft.length}/{CHAT_MAX_TEXT}</span>
        <button type="submit" className="business-assistant-send ui-button" aria-label="发送给 Orbita" disabled={!draft.trim()&&!files.length}><ArrowUp size={19}/></button>
      </div>
    </form>
    {error&&<p className="chat-error" role="status">{error}</p>}
  </section>;
}
