import { useEffect, useRef, useState } from 'react';
import type { FormEvent, KeyboardEvent } from 'react';
import {
  ArrowRight, ArrowUp, CheckCircle2, ClipboardCopy, FileSpreadsheet, Sparkles,
  FileText, Image, MessageCircle, Paperclip, PenSquare, RefreshCw, ScanSearch, CirclePause, X,
} from 'lucide-react';
import { Badge, Button, IconButton, Textarea } from '../components/ui';
import BrandMark from '../components/BrandMark';
import {
  CHAT_MAX_TEXT, CHAT_PROMPTS, validateAttachment,
  type ChatAttachment, type ChatMessage, type ChatProposal, type ChatThread,
} from '../domain/chat';
import { countWorkTab, type WorkDecisions } from '../domain/work-items';

const routine=[
  {title:'开店 5 分钟', hint:'今天要发 · 昨夜动静 · 价格红区', prompt:'执行开店例行检查：今天要发什么、价格红区有什么变化'},
  {title:'发货前',hint:'货源 · 面单 · 超重风险',prompt:'发货前检查哪些订单还没有定货源'},
  {title:'周复盘',hint:'销量 · 让利 · 商品去留',prompt:'做一份本周店铺复盘'},
  {title:'月初定盘',hint:'预算 · 上新 · 经营节奏',prompt:'制定本月经营方向和预算'},
];

function currentGreeting(){
  const hour=Number(new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Shanghai',hour:'2-digit',hourCycle:'h23'}).format(new Date()));
  return hour < 11?'早上好':hour < 18?'下午好':'晚上好';
}
function attachmentIcon(file:ChatAttachment){
  if (/\.(png|jpe?g|gif|webp)$/i.test(file.name)) return <Image size={15}/>;
  if (/\.xls[x]?$/i.test(file.name)) return <FileSpreadsheet size={15}/>;
  return <FileText size={15}/>;
}
function ProposalPanel({proposal,onDecision}:{
  proposal:ChatProposal; onDecision:(value:'simulated'|'rejected')=>void
}){
  const active=proposal.status==='ready';
  return <section className="chat-proposal" aria-label="模拟动作预览">
    <div className="chat-proposal-head">
      <span><CheckCircle2 size={16}/> {proposal.type==='price'?'调整售价':'调整库存'} · 只读预览</span>
      <Badge>{active?'等待模拟确认':proposal.status==='simulated'?'已记录模拟核对':'本地已拒绝'}</Badge>
    </div>
    <h3>{proposal.sku}</h3>
    <div className="chat-proposal-grid">
      {[['改前',proposal.before],['改后',proposal.after],
        ['影响',proposal.impact],['能撤吗',proposal.reversible]].map(([name,value])=>
        <div key={name}><small>{name}</small><strong>{value}</strong></div>)}
    </div>
    {active && <div className="chat-proposal-actions">
      <Button variant="outline" onClick={()=>onDecision('rejected')}>拒绝</Button>
      <Button variant="primary" onClick={()=>onDecision('simulated')}>确认模拟执行</Button>
    </div>}
    <p>仅模拟预览与本地状态记录。不会修改线上店铺，不能代表真实执行结果。</p>
  </section>;
}
function ChatRow({message,onEdit,onCopy,onRegenerate,onDecision,onSuggestion}:{
  message:ChatMessage;
  onEdit:()=>void;
  onCopy:()=>void;
  onRegenerate:()=>void;
  onDecision:(value:'simulated'|'rejected')=>void;
  onSuggestion:(value:string)=>void;
}){
  const assistant=message.role==='assistant';
  return <article className={'chat-message '+(assistant?'assistant':'user')} aria-label={assistant?'Orbita 模拟回复':'用户消息'}>
    {assistant&&<div className="chat-speaker"><span className="chat-speaker-icon">✦</span> Orbita <Badge>本地演示</Badge></div>}
    <div className="chat-message-copy">{message.text}</div>
    {!!message.attachments?.length&&<div className="chat-attachments">
      {message.attachments.map((f,i)=><span className="chat-file" key={f.name+i}>{attachmentIcon(f)}{f.name}</span>)}
    </div>}
    {message.proposal&&<ProposalPanel proposal={message.proposal} onDecision={onDecision}/>}
    {assistant&&!!message.suggestions?.length&&<div className="chat-followups">
      {message.suggestions.map(s=><Button key={s} variant="outline" size="sm" onClick={()=>onSuggestion(s)}>{s}<ArrowRight size={14}/></Button>)}
    </div>}
    <div className="chat-message-tools">
      <button type="button" onClick={onCopy} title="复制文字"><ClipboardCopy size={14}/> 复制</button>
      {assistant
        ? <button type="button" onClick={onRegenerate} title="重新生成本地演示回复"><RefreshCw size={14}/> 重新生成</button>
        : <button type="button" onClick={onEdit}><PenSquare size={14}/> 编辑后重发</button>}
    </div>
  </article>;
}
export default function ChatPage({
  thread,onSend,onDecide,onRegenerate,onNew,navigate,workDecisions
}:{
  thread:ChatThread | null;
  onSend:(text:string,files:ChatAttachment[])=>void;
  onDecide:(messageId:string,state:'simulated'|'rejected')=>void;
  onRegenerate:(messageId:string)=>void;
  onNew:()=>void;
  navigate:(route:string)=>void;
  workDecisions:WorkDecisions;
}){
  const [draft,setDraft]=useState('');
  const [files,setFiles]=useState<ChatAttachment[]>([]);
  const [error,setError]=useState('');
  const textarea=useRef<HTMLTextAreaElement>(null);
  const fileInput=useRef<HTMLInputElement>(null);
  const endRef=useRef<HTMLDivElement>(null);
  const messages=thread?.messages||[];
  const hasMessages=messages.length>0;
  useEffect(()=>{endRef.current?.scrollIntoView({block:'end'});},[thread?.id,messages.length]);
  useEffect(()=>{
    const keyHandler=(e:globalThis.KeyboardEvent)=>{
      if ((e.metaKey||e.ctrlKey) && e.key.toLowerCase()==='k'){
        e.preventDefault();textarea.current?.focus();
      }
    };
    window.addEventListener('keydown',keyHandler);
    return ()=>window.removeEventListener('keydown',keyHandler);
  },[]);
  function submit(e?:FormEvent){
    e?.preventDefault();
    if (!draft.trim()&&!files.length)return;
    onSend(draft,files);
    setDraft('');setFiles([]);setError('');
  }
  function keyDown(e:KeyboardEvent<HTMLTextAreaElement>){
    if(e.key==='Enter'&&!e.shiftKey&&!e.nativeEvent.isComposing){
      e.preventDefault();submit();
    }
  }
  function chooseFiles(fileList:FileList|null){
    if(!fileList)return;
    setError('');
    const selected:ChatAttachment[]=[];
    for(const f of Array.from(fileList)){
      const invalid=validateAttachment(f);
      if(invalid){setError(`${f.name}：${invalid}`);continue}
      selected.push({name:f.name,size:f.size,type:f.type});
    }
    setFiles(prev=>[...prev,...selected].slice(0,5));
    if(fileInput.current)fileInput.current.value='';
  }
  function edit(text:string){setDraft(text);textarea.current?.focus();}
  function fill(text:string){setDraft(text);textarea.current?.focus();}
  async function copy(text:string){
    try{await navigator.clipboard.writeText(text);setError('已复制到剪贴板');}
    catch{setError('复制未成功，请手动选择文字')}
  }
  const composer=<div className="native-chat-composer-area">
      <form className="native-chat-composer" onSubmit={submit}>
        {files.length>0&&<div className="chat-selected-files">{files.map((f,i)=><span key={f.name+i} className="chat-file">
          {attachmentIcon(f)} <span>{f.name}</span>
          <IconButton aria-label={'移除 '+f.name} onClick={()=>setFiles(list=>list.filter((_,n)=>n!==i))}><X size={14}/></IconButton>
        </span>)}</div>}
        <Textarea ref={textarea} value={draft} maxLength={CHAT_MAX_TEXT}
          onChange={e=>{setDraft(e.target.value);setError('')}}
          onKeyDown={keyDown} rows={2} aria-label="问 Orbita"
          placeholder="直接说就行：改价、补库存、上新、报活动，或者问店里的情况"/>
        <div className="chat-composer-actions">
          <input ref={fileInput} type="file" hidden multiple
            accept="image/png,image/jpeg,image/webp,image/gif,.png,.jpg,.jpeg,.webp,.gif,.xlsx,.xls,.json"
            onChange={e=>chooseFiles(e.currentTarget.files)} />
          <IconButton aria-label="添加图片或表格" title="仅保留文件名，不读取或上传内容"
            onClick={()=>fileInput.current?.click()}><Paperclip size={20}/></IconButton>
          <span className="chat-composer-limit">{draft.length}/{CHAT_MAX_TEXT}</span>
          <Button type="submit" variant="primary" size="icon"
            aria-label="发送" disabled={!draft.trim()&&!files.length}><ArrowUp size={19}/></Button>
        </div>
      </form>
      {error&&<p className="chat-error" role="status">{error}</p>}
    </div>;
  return <main className={'native-chat '+(hasMessages?'has-messages':'is-home')}>
    <div className="native-chat-scroll" aria-label="对话内容">
      {!hasMessages?<div className="chat-home">
        <header className="chat-hero">
          <div className="chat-hero-orbit" aria-hidden="true"><BrandMark orbiting/></div>
          <span className="chat-hero-eyebrow"><Sparkles size={15}/> ORBITA · AI 经营助手</span>
          <h1><span>{currentGreeting()}</span>，想让店铺做点什么？</h1>
          <p>说出经营目标，Orbita 帮你分析并准备方案。</p>
        </header>
        {composer}
        <section className="chat-prompt-list ui-choice-row" aria-label="示例提问">
          {CHAT_PROMPTS.map(x=><button key={x} onClick={()=>fill(x)}>{x}</button>)}
        </section>
        <section className="chat-home-inspection" aria-label="店铺巡检">
          <ScanSearch size={19} className="chat-inspection-icon" aria-hidden="true"/>
          <div className="chat-inspection-copy"><strong>店铺巡检</strong><span><CirclePause size={13} aria-hidden="true"/> 自动巡检未开启</span></div>
          <button type="button" className="chat-inspection-action" onClick={()=>fill('检查店铺价格、库存、订单和经营异常，并告诉我当前可执行的检查范围')} title="先填写巡检请求；未连接实际巡检服务">了解巡检 <ArrowRight size={15}/></button>
          <button type="button" className="chat-inspection-settings" onClick={()=>navigate('/settings/automation')}>设置 <ArrowRight size={14}/></button>
        </section>
        <div className="chat-home-workspace">
          <section className="chat-home-panel chat-home-routines" aria-label="常用经营任务">
            <div className="chat-home-panel-heading"><h2>常用任务</h2><Button variant="ghost" size="sm" onClick={()=>navigate('/settings/automation')}>任务设置 <ArrowRight size={14}/></Button></div>
            <div className="chat-routine-grid">{routine.map(x=><button type="button" className="chat-routine" key={x.title} onClick={()=>fill(x.prompt)}>
              <span><strong>{x.title}</strong></span><p>{x.hint}</p>
            </button>)}</div>
          </section>
          <section className="chat-home-panel chat-home-continue" aria-label="继续经营任务">
            <div className="chat-home-panel-heading"><h2>待办处理</h2><Button variant="ghost" size="sm" onClick={()=>navigate('/todo')}>查看全部 <ArrowRight size={14}/></Button></div>
            <div className="chat-home-task-list"><button type="button" className="chat-home-task-row" onClick={()=>navigate('/todo')}><div className="chat-home-task-icon"><CheckCircle2 size={17}/></div><div><strong>{countWorkTab('pending',workDecisions)} 项方案待确认</strong><p>核对方案并决定是否执行</p></div></button>
            <button type="button" className="chat-home-task-row" onClick={()=>navigate('/todo')}><div className="chat-home-task-icon"><MessageCircle size={17}/></div><div><strong>{countWorkTab('attention',workDecisions)} 项经营提醒</strong><p>查看待关注的经营变化</p></div></button></div>
          </section>
        </div>
      </div>:<div className="chat-conversation">
        {messages.map(message=><ChatRow key={message.id} message={message}
          onCopy={()=>copy(message.text)}
          onEdit={()=>edit(message.text)}
          onRegenerate={()=>onRegenerate(message.id)}
          onDecision={state=>onDecide(message.id,state)}
          onSuggestion={fill}/>)}
        <div ref={endRef}/>
      </div>}
    </div>
    {hasMessages&&composer}
  </main>;
}
