import {useState} from 'react';
import {ArrowRight,Bell,CalendarDays,CheckCircle2,Search,ShieldAlert} from 'lucide-react';
import {Badge,Button,Card} from '../components/ui';
import type {ProductChanges} from '../domain/products';
import {productCounts} from '../domain/products';
import {countWorkTab,type WorkDecisions} from '../domain/work-items';
type GrowthView='价格'|'活动'|'广告'|'内容';
type PromoTab='活动日历'|'决策卡'|'回价义务'|'护栏倒计时';
const promoItems=[
  {name:'Скидки недели',dates:'10-08 → 10-20',sub:'平台自动加入风险 · 请核对真实活动状态',state:'参加中（原型快照）'},
  {name:'11.11 Распродажа',dates:'11-09 → 11-13',sub:'大促候选，报价需满足利润底线',state:'即将开始（原型快照）'},
  {name:'Старое предложение',dates:'09-01 → 10-01',sub:'历史活动，价格恢复情况需另行核对',state:'已结束（原型快照）'},
];
export default function GrowthPage({navigate,route,products,decisions}:{
  navigate:(path:string)=>void;route:string;products:ProductChanges;decisions:WorkDecisions
}){
  const [view,setView]=useState<GrowthView>('价格');
  const [promoTab,setPromoTab]=useState<PromoTab>('活动日历');
  const [query,setQuery]=useState('');
  const [note,setNote]=useState('');
  const count=productCounts(products);
  const promotions=route.startsWith('/growth/promotions');
  const views:{title:GrowthView,value:string,description:string}[]=[
    {title:'价格',value:String(count.price),description:'价格偏高 · 改价等你审批'},
    {title:'活动',value:'1',description:'涉及 1 个原型活动'},
    {title:'广告',value:'未开启',description:'广告账户能力未开放'},
    {title:'内容',value:'80',description:'3 个商品平均演示内容分'},
  ];
  return <main className="native-workspace v4-growth">
    <header className="workspace-header"><div>
      <h1>增长{promotions?' · 活动':''}</h1>
      <p>{promotions?'活动日历、可报名判断和回价义务':'价格、活动、广告、内容四个杠杆，以及还需要处理的事'} · 非实时演示</p></div>
      <Button variant="outline" onClick={()=>navigate(promotions?'/growth':'/growth/promotions')}>
        {promotions?'返回增长概览':'查看活动日历'} <ArrowRight size={16}/></Button></header>
    {promotions?<div className="workspace-column">
      <nav className="workspace-tabs ui-tab-list" aria-label="活动视图">{(['活动日历','决策卡','回价义务','护栏倒计时'] as PromoTab[])
        .map(x=><button key={x} className={promoTab===x?'active':''} onClick={()=>setPromoTab(x)}>{x}</button>)}</nav>
      <Card className="workspace-alert"><ShieldAlert size={18}/><div><strong>大促跑道期 · 时间与规则为原型演示</strong>
        <p>临近 11.11 时普通促销和抬价可能受到限制；请以 Ozon 当期发布的活动规则为准。</p></div></Card>
      {promoTab==='活动日历'&&<section className="workspace-column">
        <div className="workspace-row"><h2>活动列表</h2>
          <label className="workspace-search"><Search size={16}/><input value={query}
            onChange={e=>setQuery(e.target.value)} placeholder="搜索活动" aria-label="搜索活动"/></label></div>
        {promoItems.filter(x=>x.name.toLowerCase().includes(query.toLowerCase())).map(x=>
          <Card key={x.name} className="workspace-list-card"><div><Badge>{x.state}</Badge>
            <h3>{x.name}</h3><p>{x.dates} · {x.sub}</p></div>
            <Button variant="outline" onClick={()=>setPromoTab('决策卡')}>查看决策卡 <ArrowRight size={15}/></Button></Card>)}
      </section>}
      {promoTab==='决策卡'&&<div className="workspace-grid">
        {['可报','不报','判不了','平台加入待核'].map((x,i)=><Card key={x}>
          <Badge>{x}</Badge><h3>{['商品利润满足护栏','折后价格可能低于保本','缺少平台实时条件','QHBB01-2'][i]}</h3>
          <p>这是静态决策样例，不代表已经提交 Ozon 活动。</p>
          <Button variant="outline" onClick={()=>navigate('/todo')}>去待办确认</Button></Card>)}</div>}
      {promoTab==='回价义务'&&<Card><h3>活动结束后，价格是否回到原位？</h3><p>当前没有从平台读回的可核对证据。请进入商品详情检查价格，勿自动判断成功。</p>
        <Button variant="outline" onClick={()=>navigate('/products')}>查看商品</Button></Card>}
      {promoTab==='护栏倒计时'&&<Card><h3><CalendarDays size={18}/> 最低价护栏</h3><p>原型没有足够的实时活动与价格历史，不计算虚假的剩余天数。</p>
        <Button variant="outline" onClick={()=>navigate('/strategy')}>调整经营边界</Button></Card>}
    </div>:<>
      <div className="workspace-grid four">{views.map(item=><button key={item.title}
        className={'workspace-summary'+(view===item.title?' active':'')} onClick={()=>setView(item.title)}>
        <span>{item.title}</span><strong>{item.value}</strong><small>{item.description}</small></button>)}</div>
      <div className="workspace-actions"><Button variant="ghost" onClick={()=>navigate('/strategy')}>托管设置 <ArrowRight size={16}/></Button></div>
      <Card className="workspace-feature">
        {view==='价格'&&<>
          <div className="workspace-row"><h2>价格指数 · 3 个在架商品</h2><Badge>红区 {count.price}</Badge></div>
          <p>演示商品 CZ7271 价格红区，需先查看利润、再预览调整。</p>
          <div className="workspace-statrow"><span>绿档：{3-count.price}</span><span>黄档：0</span><span>红档：{count.price}</span></div>
          <div className="workspace-row"><strong>待审批方案</strong><span>{countWorkTab('pending',decisions)} 条等待核对</span></div>
          <div className="workspace-actions"><Button variant="primary" onClick={()=>navigate('/products')}>去商品改价</Button>
            <Button variant="outline" onClick={()=>navigate('/todo')}>查看审批队列</Button></div>
        </>}
        {view==='活动'&&<><h2>活动管理</h2><p>演示中 1 个活动由平台自动加入，折扣可能突破保本参考价。</p>
          <Button variant="primary" onClick={()=>navigate('/growth/promotions')}>活动决策与日历</Button></>}
        {view==='广告'&&<><h2>广告 · 未开启</h2><p>演示环境无实时广告账单或开启权限。</p>
          <Button variant="outline" onClick={()=>navigate('/settings/ads')}>查看广告账户状态</Button></>}
        {view==='内容'&&<><h2>商品内容</h2><p>平均演示内容分 80。上传与自动生成图视频需要独立服务，当前未接入。</p>
          <Button variant="outline" onClick={()=>navigate('/settings/media')}>商品图与视频设置</Button></>}
      </Card>
    </>}
    <footer className="workspace-footer"><CheckCircle2 size={16}/> 数据来自原始静态演示与本地修改，不是平台实时查询。
      <Button variant="ghost" onClick={()=>navigate('/kb')}>查看官方规则 <ArrowRight size={15}/></Button></footer>
    {note&&<p role="status">{note}</p>}
  </main>;
}
