import {useEffect,useState} from 'react';
import {ArrowRight,Check,FileSpreadsheet,Link2,PackagePlus,Trash2} from 'lucide-react';
import {Badge,Button,Card,TextInput} from '../components/ui';
type Draft={id:string;sku:string;title:string;price:number;source:string;createdAt:number;status:'preview'|'confirmed'};
const STORAGE='orbita-native-product-drafts-v1';
const MAX_RECORDS=100;
function getDrafts():Draft[]{
  try {const raw:unknown=JSON.parse(localStorage.getItem(STORAGE)||'[]');
    if(!Array.isArray(raw))return [];
    return raw.filter((v):v is Draft=>v&&typeof v==='object'&&typeof v.id==='string'
      &&typeof v.sku==='string'&&typeof v.title==='string'&&typeof v.price==='number').slice(0,MAX_RECORDS)
  }catch{return []}
}
function makeDraft(row:Record<string,unknown>):Draft|null{
  const sku=String(row.sku||row['货号']||'').trim().slice(0,80);
  const title=String(row.title||row['标题']||'').trim().slice(0,180);
  const price=Number(row.price??row['价格']);
  if(!sku||!title||!Number.isFinite(price)||price<=0||price>999999)return null;
  return {id:crypto.randomUUID(),sku,title,price,source:String(row.source||row['货源链接']||'').slice(0,500),
    createdAt:Date.now(),status:'preview'};
}
function parseCsv(text:string):string[][]{
  const result:string[][]=[];let row:string[]=[],field='',quoted=false;
  for(let i=0;i<text.length;i++){
    const ch=text[i];
    if(ch==='"'){
      if(quoted&&text[i+1]==='"'){field+='"';i++}else quoted=!quoted;
    }else if(ch===','&&!quoted){
      row.push(field.trim());field='';
    }else if((ch==='\n'||ch==='\r')&&!quoted){
      if(ch==='\r'&&text[i+1]==='\n')i++;
      row.push(field.trim());if(row.some(Boolean))result.push(row);
      row=[];field='';
    }else field+=ch;
  }
  if(quoted)throw Error('CSV 存在未闭合的引号');
  row.push(field.trim());if(row.some(Boolean))result.push(row);
  return result;
}
export function parseTable(text:string,extension:string):Draft[]{
  if(extension==='json'){
    const json:unknown=JSON.parse(text);
    if(!Array.isArray(json))throw Error('JSON 内容必须是商品对象数组');
    return json.slice(0,MAX_RECORDS).map(r=>makeDraft(r as Record<string,unknown>)).filter((x):x is Draft=>!!x);
  }
  const lines=parseCsv(text.replace(/^\uFEFF/,'')).slice(0,MAX_RECORDS+1);
  const headers=lines.shift()||[];
  if(!headers.length)throw Error('缺少表头');
  return lines.map(cols=>{
    return makeDraft(Object.fromEntries(headers.map((h,i)=>[h,cols[i]||''])));
  }).filter((x):x is Draft=>!!x);
}
export default function NewProductPage({navigate}:{navigate:(route:string)=>void}){
  const [drafts,setDrafts]=useState<Draft[]>(getDrafts);
  const [sku,setSku]=useState(''),[title,setTitle]=useState(''),[price,setPrice]=useState(''),[source,setSource]=useState('');
  const [message,setMessage]=useState('');
  const [bulkOpen,setBulkOpen]=useState(false);
  useEffect(()=>{try{localStorage.setItem(STORAGE,JSON.stringify(drafts))}catch{setMessage('存储空间不足，未保存本地草稿')}},[drafts]);
  const create=()=>{
    const draft=makeDraft({sku,title,price,source});
    if(!draft){setMessage('请填写货号、标题和大于零的价格');return}
    setDrafts(rows=>[draft,...rows].slice(0,MAX_RECORDS));
    setSku('');setTitle('');setPrice('');setSource('');
    setMessage('已准备本地上新预览。不会上传或修改线上商品。');
  };
  async function importFile(file:File|undefined){
    if(!file)return;
    if(file.size>2*1024*1024){setMessage('演示导入单文件最大 2 MB');return}
    const ext=file.name.toLowerCase().split('.').pop()||'';
    if(!['csv','json'].includes(ext)){setMessage('本地原生导入目前仅支持 CSV / JSON；Excel 文件不能假装已经解析。');return}
    try {
      const rows=parseTable(await file.text(),ext);
      if(!rows.length){setMessage('没有找到合法的商品数据：必须包含货号、标题、价格');return}
      setDrafts(old=>[...rows,...old].slice(0,MAX_RECORDS));
      setMessage('读取了 '+rows.length+' 条本地商品预览（未上传或提交）。');
    }catch(e){setMessage('无法读取文件：'+(e instanceof Error?e.message:'文件格式错误'))}
  }
  function markConfirmed(id:string){
    setDrafts(list=>list.map(x=>x.id===id?{...x,status:'confirmed'}:x));
    setMessage('本地核对完成。尚未上传到 Ozon，商品未上架。');
  }
  return <main className="native-workspace new-product-page">
    <header className="workspace-header"><div>
      <h1>上新</h1><p>创建商品草稿，预览并核对后保存。</p></div>
      <Button variant="outline" onClick={()=>navigate('/products')}>返回商品 <ArrowRight size={16}/></Button></header>
    <div className="v4-stacked-flow">
      <Card className="workspace-feature"><h2><PackagePlus size={18}/> 单个商品</h2>
        <div className="new-product-fields">
        <label className="workspace-field">货号（必填）<TextInput value={sku} onChange={e=>setSku(e.target.value)} placeholder="例如 NEW-001"/></label>
        <label className="workspace-field">商品标题（必填）<TextInput value={title} onChange={e=>setTitle(e.target.value)}/></label>
        <label className="workspace-field">建议售价（RUB）<TextInput type="number" min="1" value={price} onChange={e=>setPrice(e.target.value)}/></label>
        <label className="workspace-field">货源链接（仅记录，不抓取）<TextInput type="url" value={source} onChange={e=>setSource(e.target.value)} placeholder="https://detail.1688.com/..."/></label>
        </div><Button variant="primary" onClick={create}>生成本地预览 <ArrowRight size={16}/></Button>
      </Card>
      <Card className="workspace-feature"><button className="v4-section-toggle" aria-expanded={bulkOpen} onClick={()=>setBulkOpen(v=>!v)}><FileSpreadsheet size={18}/> 批量导入 <span>{bulkOpen?'收起':'展开'}</span></button>
        {bulkOpen&&<div className="v4-section-body">
        <p>支持表头为「货号、标题、价格、货源链接」的 CSV；也可以上传包含 sku/title/price 的 JSON 数组。</p>
        <input aria-label="上传 CSV 或 JSON" type="file" accept=".csv,.json,text/csv,application/json"
          onChange={e=>{void importFile(e.target.files?.[0]);e.target.value=''}}/>
        <p>每次最多处理 100 条商品草稿，不接触真实平台。</p></div>}
      </Card>
    </div>
    {message&&<p className="workspace-confirmation" role="status">{message}</p>}
    <section className="workspace-column new-product-results"><div className="workspace-row"><h2>上新预览 · {drafts.length}</h2>
      {drafts.length>0&&<Button variant="ghost" onClick={()=>{
        if(window.confirm('清空本地上新预览？'))setDrafts([]);
      }}><Trash2 size={15}/> 清空</Button>}</div>
      {drafts.map(d=><Card className="workspace-list-card" key={d.id}>
        <div><h3>{d.sku} · {d.title}</h3><p>{d.price} RUB · {d.source||'暂无货源链接'}</p>
          <Badge>{d.status==='confirmed'?'本地核对完成 · 未上架':'等待本地核对'}</Badge></div>
        <div className="workspace-actions">
          {d.status==='preview'&&<Button variant="primary" size="sm" onClick={()=>markConfirmed(d.id)}><Check size={15}/> 核对预览</Button>}
          <Button variant="ghost" size="sm" onClick={()=>setDrafts(v=>v.filter(x=>x.id!==d.id))}><Trash2 size={15}/> 删除</Button>
        </div>
      </Card>)}
      {!drafts.length&&<Card className="workspace-empty">尚无本地上新草稿，先输入一个商品或导入文件。</Card>}
    </section>
  </main>;
}
