import { useMemo, useRef, useState } from 'react';
import type { Dispatch, SetStateAction } from 'react';
import {
  ArrowDownWideNarrow, Bell, Check, CheckCheck, ChevronDown,
  ClipboardCheck, Clock3, Info, RefreshCw, RotateCcw, ShieldCheck
} from 'lucide-react';
import { Badge, Button, Card } from '../components/ui';
import {
  ALL_WORK, categoryOptions,
  countWorkTab, workStatus, workTab,
  type CategoryFilter, type WorkDecisions, type WorkItem, type WorkTab,
} from '../domain/work-items';

const tabs: { id: WorkTab; title: string; icon: typeof Bell; hint: string }[] = [
  { id:'pending', title:'待审批', icon:ClipboardCheck, hint:'审批通过后才会进入模拟核对' },
  { id:'running', title:'运行与核对', icon:RotateCcw, hint:'模拟执行已核对的结果' },
  { id:'attention', title:'需关注', icon:Bell, hint:'紧急和今天要看的提醒' },
  { id:'information', title:'仅供了解', icon:Info, hint:'看一眼即可，不用动手' },
  { id:'processed', title:'已处理', icon:CheckCheck, hint:'已处理或已读的事项' },
];
type Order = 'urgent' | 'new' | 'expires';

export default function TodoPage({
  navigate, decisions, setDecisions
}: {
  navigate: (route: string) => void;
  decisions: WorkDecisions;
  setDecisions: Dispatch<SetStateAction<WorkDecisions>>;
}) {
  const [tab, setTab] = useState<WorkTab>('pending');
  const [category, setCategory] = useState<CategoryFilter>('全部');
  const [order, setOrder] = useState<Order>('urgent');
  const [expanded, setExpanded] = useState<string|null>(null);
  const [focusedIndex, setFocusedIndex] = useState(0);
  const [stamp, setStamp] = useState(() => new Date().toLocaleTimeString('zh-CN', {
    timeZone:'Asia/Shanghai',hour:'2-digit',minute:'2-digit',hour12:false
  }));
  const itemRefs = useRef<Map<string,HTMLDivElement>>(new Map());

  const tabItems = useMemo(() => ALL_WORK.filter(item => workTab(item,decisions) === tab),[tab,decisions]);
  const filtered = useMemo(() => tabItems
    .filter(item => category === '全部' || item.category === category)
    .sort((a,b) => order==='new' ? b.importance-a.importance : a.importance-b.importance),
  [tabItems,category,order]);
  const counts = useMemo(() => Object.fromEntries(tabs.map(x=>[x.id,countWorkTab(x.id,decisions)])),[decisions]);
  const setDecision=(id:string,status:'verified'|'dismissed'|'seen')=>{
    setDecisions(prev=>({...prev,[id]:status}));
    setExpanded(null);
  };
  const resetDemo=()=>{
    if (!window.confirm('重置本地演示中的审批和提醒状态？此操作不会影响真实店铺。')) return;
    setDecisions({});setTab('pending');setCategory('全部');setExpanded(null);
  };
  function switchTab(next: WorkTab){setTab(next);setCategory('全部');setExpanded(null);setFocusedIndex(0)}
  function selectItem(index: number) {
    const item = filtered[index];
    if (item) {setFocusedIndex(index);itemRefs.current.get(item.id)?.focus()}
  }
  function onKeyboard(e:React.KeyboardEvent<HTMLElement>){
    const target=e.target as HTMLElement;
    if (target.closest('input,textarea,select,button,a,[contenteditable="true"]') || e.metaKey || e.ctrlKey || e.altKey) return;
    const focused=filtered[focusedIndex];
    if (e.key==='j' || e.key==='J') {e.preventDefault();selectItem(Math.min(filtered.length-1,focusedIndex+1))}
    if (e.key==='k' || e.key==='K') {e.preventDefault();selectItem(Math.max(0,focusedIndex-1))}
    if (e.key==='Escape') {setExpanded(null)}
    if (!focused) return;
    if (e.key==='Enter') {e.preventDefault();setExpanded(x=>x===focused.id?null:focused.id)}
    if ((e.key==='y'||e.key==='Y') && focused.kind==='approval' && tab==='pending') {
      e.preventDefault();setExpanded(focused.id);
    }
    if ((e.key==='n'||e.key==='N') && focused.kind==='approval' && tab==='pending') {
      e.preventDefault();setDecision(focused.id,'dismissed');
    }
    if ((e.key==='a'||e.key==='A') && focused.kind==='notice' && tab!=='processed') {
      e.preventDefault();setDecision(focused.id,'seen');
    }
  }
  return <main className="native-todo" onKeyDown={onKeyboard}>
    <header className="todo-header">
      <div><h1>待办</h1><p>审批方案、核对执行与处理提醒</p>
      </div>
      <div className="todo-header-actions">
        <Badge>本地演示数据</Badge>
        <Button variant="outline" onClick={() => setStamp(new Date().toLocaleTimeString('zh-CN',{
          timeZone:'Asia/Shanghai',hour:'2-digit',minute:'2-digit',hour12:false
        }))}><RefreshCw size={15}/> 刷新 · {stamp}（北京）</Button>
      </div>
    </header>
    <div className="todo-tabs ui-tab-list" role="tablist" aria-label="待办状态">
      {tabs.map(x=>{const Icon=x.icon;return <button key={x.id} type="button" role="tab"
        aria-selected={tab===x.id} title={x.hint} className={'todo-tab'+(tab===x.id?' active':'')}
        onClick={()=>switchTab(x.id)}>
        <Icon size={17} strokeWidth={1.7}/><span>{x.title}</span><strong>{counts[x.id]}</strong>
      </button>})}
    </div>
    <div className="todo-controls">
      <div className="todo-chips ui-choice-row" role="group" aria-label="业务分类">
        {categoryOptions.map(x=>{
          const amount=tabItems.filter(i=>i.category===x).length;
          return <button key={x} aria-pressed={category===x}
            className={'todo-chip'+(category===x?' active':'')}
            onClick={()=>{setCategory(x);setFocusedIndex(0);setExpanded(null)}}>{x}
            {x!=='全部'&&amount>0&&<span>{amount}</span>}
          </button>
        })}
      </div>
      <label className="todo-order"><ArrowDownWideNarrow size={16}/>
        <span>排序</span>
        <select value={order} onChange={e=>setOrder(e.target.value as Order)}>
          <option value="urgent">最急</option><option value="new">最新</option><option value="expires">快过期</option>
        </select><ChevronDown size={15}/>
      </label>
    </div>
    <section className="todo-list" aria-label={tabs.find(x=>x.id===tab)?.title}>
      {filtered.length === 0 ? <Card className="todo-empty">
        <ShieldCheck size={26}/><strong>{tab==='processed'?'还没有处理过的事':'当前分类没有待办'}</strong>
        <p>{tab==='processed'?'做完的、不做的、看过的都收在这里。':'可切换状态或分类查看其他事项。'}</p>
        {tab==='processed'&&<Button variant="outline" onClick={resetDemo}>重置演示数据</Button>}
      </Card> : filtered.map((item,index)=>{
        const shown=expanded===item.id;
        const status=workStatus(item,decisions);
        const processed=tab==='processed';
        return <Card key={item.id} className={'todo-item'+(focusedIndex===index?' focused':'')}
          tabIndex={0} onFocus={()=>setFocusedIndex(index)}
          onClick={()=>setFocusedIndex(index)}>
          <div ref={node=>{if(node)itemRefs.current.set(item.id,node);else itemRefs.current.delete(item.id)}}
            className="todo-item-inner" tabIndex={-1}>
            <div className="todo-item-title">
              <span className={'todo-kind '+(item.kind==='notice'?'notice':'approval')}>
                {item.label}</span>
              <strong>{item.sku}</strong>
              {processed&&<Badge>{status==='verified'?'模拟核对完成':status==='dismissed'?'不做':'已阅读'}</Badge>}
            </div>
            <h2>{item.summary}</h2>
            <p className="todo-reason">{item.kind==='approval'?'为什么：'+item.reason:item.detail}</p>
            {item.kind==='approval'&&tab==='pending'&&<p className="todo-expiry">
              <Clock3 size={14}/> 系统提出 · 本地模拟，实际操作前须确认店铺状态</p>}
            {item.kind==='approval'&&shown&&tab==='pending'&&<div className="v4-drawer-backdrop" onClick={e=>{e.stopPropagation();setExpanded(null)}}><aside role="dialog" aria-modal="true" aria-label={item.sku+' 审批详情'} className="v4-detail-drawer" onClick={e=>e.stopPropagation()}>
              <div className="v4-drawer-heading"><h2>{item.sku} · 审批核对</h2><Button variant="ghost" onClick={()=>setExpanded(null)}>关闭</Button></div><p>{item.summary}</p><p>{item.reason}</p><div className="todo-preview">
              <h3>执行前核对</h3>
              <div className="todo-preview-grid">
                <div><small>改前</small><strong>{item.before}</strong></div>
                <div><small>改后</small><strong>{item.after}</strong></div>
                <div><small>影响</small><strong>{item.impact}</strong></div>
                <div><small>能撤吗</small><strong>{item.reversible}</strong></div>
              </div>
              <p className="todo-demo-warning">仅更新本地演示状态，不会连接 Ozon 或修改真实商品。</p>
            </div><div className="v4-drawer-actions"><Button variant="outline" onClick={()=>setExpanded(null)}>再想想</Button><Button variant="primary" onClick={()=>setDecision(item.id,'verified')}>确认模拟核对</Button></div></aside></div>}
            <div className="todo-item-actions">
              {item.kind==='approval'&&tab==='pending'&&
                (shown ? <>
                  <Button variant="primary" onClick={()=>setDecision(item.id,'verified')}><Check size={16}/> 确认模拟核对</Button>
                  <Button variant="outline" onClick={()=>setExpanded(null)}>再想想</Button>
                </> : <>
                  <Button variant="primary" onClick={()=>setExpanded(item.id)}>同意 · 先预览</Button>
                  <Button variant="outline" onClick={()=>setDecision(item.id,'dismissed')}>不做</Button>
                </>)}
              {item.kind==='notice'&&!processed&&<>
                <Button variant="primary" onClick={()=>setDecision(item.id,'seen')}>知道了</Button>
                <Button variant="outline" onClick={()=>navigate(item.detailRoute)}>看详情</Button>
              </>}
              {processed&&<span className="todo-processed-note">该事项已经归档到本地演示记录。</span>}
            </div>
          </div>
        </Card>})}
    </section>
    <footer className="todo-footer">
      <span>J / K 上下 · Enter 展开 · Y 同意 · N 不做 · A 知道了 · Esc 收起</span>
      <span className="todo-footer-actions">本地模拟，不连接真实店铺
        <Button variant="ghost" size="sm" onClick={resetDemo}>重置演示状态</Button>
      </span>
    </footer>
  </main>;
}
