import { useId } from 'react';

/** Shared Orbit mark with the original cyan tip and blue-purple ring. */
export default function BrandMark({orbiting=false}:{orbiting?:boolean}){
  const gradient=useId().replace(/:/g,'');
  return <svg className="brand-mark" viewBox="0 0 56 40" fill="none" aria-hidden="true">
    <defs><linearGradient id={gradient} x1="5" y1="34" x2="49" y2="6" gradientUnits="userSpaceOnUse">
      <stop stopColor="#6759FF"/><stop offset="0.55" stopColor="#617BFF"/><stop offset="1" stopColor="#A75DF4"/>
    </linearGradient></defs>
    <ellipse cx="28" cy="20" rx="25" ry="12" transform="rotate(-27 28 20)" stroke={`url(#${gradient})`} strokeWidth="3.7"/>
    <circle cx="27" cy="21" r="7" fill="#6576FF"/>
    {orbiting ? <g transform="rotate(-27 28 20)"><circle cx="53" cy="20" r="3.2" fill="#37E2DF"><animateMotion dur="12s" repeatCount="indefinite" path="M 0 0 A 25 12 0 1 1 -50 0 A 25 12 0 1 1 0 0"/></circle></g> : <circle cx="50.28" cy="8.65" r="3.2" fill="#37E2DF"/>}
  </svg>;
}
