import {useEffect,useState} from 'react';
import {ArrowRight,BarChart3,Calculator,CheckCircle2,Clock3,LockKeyhole,ShieldCheck} from 'lucide-react';
import {Badge,Button,Card,TextInput} from '../components/ui';
import {readPrototypeSettings,savePrototypeSettings,type PrototypeSettings} from '../domain/native-store';
type Panel='方向'|'预算与阶段'|'自动化'|'周报';
const questions=[
  {title:'资金能撑几个回款周期',opts:['不到 1.5 个','1.5–2 个','2–3 个','3 个以上']},
  {title:'工厂条件',opts:['现款现货，起订 ≥500 件','现款，小起订（≤50 件）','有 30 天账期','账期 ≥45 天或自有工厂']},
  {title:'物流友好度',opts:['超过 1kg 或体积大','0.5–1kg','≤0.5kg，小体积','≤0.5kg 且单价高']},
  {title:'类目经济性',opts:['服装鞋类或无证','需认证但能办','免认证、佣金中等','免认证、佣金低退货低']},
  {title:'团队经验',opts:['一人兼职','一人全职','2–3 人，有内容产线','有跨境经验的团队']},
  {title:'位置与履约',opts:['内陆，远离集货仓','华南 / 华东','靠近 FBP 中国仓','有俄罗斯仓']},
  {title:'时间窗',opts:['距旺季不到 45 天','平常时段','旺季前 2–3 个月']},
];
function save(values:PrototypeSettings){savePrototypeSettings(values)}
export default function StrategyPage({route,navigate}:{
  route:string;navigate:(path:string)=>void
}){
  const param=new URLSearchParams(route.split('?')[1]).get('tab');
  const initial:Panel=route.includes('automation')||param==='automation'?'自动化':
    param==='budget'?'预算与阶段':param==='report'?'周报':'方向';
  const [tab,setTab]=useState<Panel>(initial);
  const [state,setState]=useState<PrototypeSettings>(readPrototypeSettings);
  const [saved,setSaved]=useState('');
  const [editing,setEditing]=useState<'方向'|'预算与阶段'|null>(null);
  useEffect(()=>{if(!editing)return;const close=(e:KeyboardEvent)=>{if(e.key==='Escape')setEditing(null)};window.addEventListener('keydown',close);return()=>window.removeEventListener('keydown',close)},[editing]);
  useEffect(()=>{save(state)},[state]);
  const set=(name:string,value:string|number|boolean)=>{setState(old=>({...old,[name]:value}));setSaved('')};
  const answers=questions.map((_,i)=>Number(state['strategy-q'+i]||0));
  const total=answers.reduce((a,b)=>a+b,0);
  const maxScore=questions.reduce((a,q)=>a+q.opts.length-1,0);
  const funds=Number(state['strategy-funds']||0),cost=Number(state['strategy-cycle']||0);
  const runway=cost>0?(funds/cost).toFixed(1):'未填写';
  const level=total<=6?'保守':total<=13?'稳健':'进取';
  const scoreRange=total+'/'+maxScore;
  function markSaved(message:string){setSaved(message+'（仅保存在本机，尚未生效于 Ozon）')}
  return <main className="native-workspace v4-strategy">
    <header className="workspace-header"><div>
      <h1>经营策略</h1><p>走多快、花多少、系统自动做到哪一步、这周怎么样</p></div>
      <Badge>本地策略草稿</Badge></header>
    <div className="workspace-grid four">
      {[
        ['经营方向',String(state['strategy-selected-level']||'尚未确定'),'需管理者确认'],
        ['盘点得分',scoreRange,'按演示资源条件计算'],
        ['系统权限','全部待审批','不触发后台任务'],
        ['资金跑道',runway,'按周期成本估算'],
      ].map(([title,value,desc])=><div className="workspace-summary" key={title}>
        <span>{title}</span><strong>{value}</strong><small>{desc}</small></div>)}
    </div>
    <nav className="workspace-tabs ui-tab-list">{(['方向','预算与阶段','自动化','周报'] as Panel[]).map(x=>
      <button key={x} className={x===tab?'active':''} onClick={()=>{setTab(x);setEditing(null)}}>{x}</button>)}</nav>
    {tab==='方向'&&<div className="v4-strategy-list">
      <button className="v4-strategy-entry" onClick={()=>setEditing('方向')}><strong>经营方向</strong><span>{String(state['strategy-selected-level']||'尚未确定')} · 资源盘点 {scoreRange}</span><ArrowRight size={17}/></button>
      <button className="v4-strategy-entry" onClick={()=>{setTab('预算与阶段');setEditing('预算与阶段')}}><strong>资金与预算</strong><span>可动用资金 {funds||'待填写'} 元 · 跑道 {runway}</span><ArrowRight size={17}/></button>
      <button className="v4-strategy-entry" onClick={()=>{setTab('自动化');setEditing(null)}}><strong>Agent 自动化权限</strong><span>全部待审批 · 未连接真实执行</span><ArrowRight size={17}/></button>
      <button className="v4-strategy-entry" onClick={()=>{setTab('周报');setEditing(null)}}><strong>经营回顾</strong><span>本地演示周报</span><ArrowRight size={17}/></button>
    </div>}
    {editing==='方向'&&<div className="v4-drawer-backdrop" onClick={()=>setEditing(null)}><aside className="v4-detail-drawer" role="dialog" aria-modal="true" aria-label="经营方向配置" onClick={e=>e.stopPropagation()}><div className="v4-drawer-heading"><h2>经营方向配置</h2><Button variant="ghost" onClick={()=>setEditing(null)}>关闭</Button></div><div className="workspace-column">
      <Card className="workspace-feature"><h2>先盘一遍手上有什么</h2>
        <p>填写资源条件后计算经营档位。这个评分只是演示模型，不代表投资或平台决策。</p>
        <div className="workspace-grid two">
          {questions.map((q,i)=><label className="workspace-field" key={q.title}>{q.title}
            <select value={answers[i]} onChange={e=>set('strategy-q'+i,+e.target.value)}>
              {q.opts.map((opt,index)=><option key={opt} value={index}>{opt}（{index} 分）</option>)}
            </select></label>)}
          <label className="workspace-field">可动用资金（元）
            <TextInput type="number" min="0" value={String(state['strategy-funds']||'')}
              onChange={e=>set('strategy-funds',e.target.value)} placeholder="输入金额"/></label>
          <label className="workspace-field">一个周期需要成本（元）
            <TextInput type="number" min="0" value={String(state['strategy-cycle']||'')}
              onChange={e=>set('strategy-cycle',e.target.value)} placeholder="采购、投放、让利"/></label>
          <label className="workspace-field">新 SKU 首批成本（元）
            <TextInput type="number" min="0" value={String(state['strategy-sku-cost']||'')}
              onChange={e=>set('strategy-sku-cost',e.target.value)}/></label>
          <label className="workspace-field">每周可投入人日
            <TextInput type="number" min="0" value={String(state['strategy-days']||'')}
              onChange={e=>set('strategy-days',e.target.value)}/></label>
        </div>
        <div className="workspace-statrow"><span><Calculator size={17}/> 盘点合计 {scoreRange}</span>
          <span>建议档位：<strong>{level}</strong></span><span>资金跑道：{runway}</span></div>
        <Button variant="primary" onClick={()=>markSaved('资源盘点已保存')}>保存盘点</Button>
      </Card>
      <Card className="workspace-feature"><h2>定这家店走多快</h2>
        <p>保存后只是本地经营方向草稿；正式改变自动化策略需要服务端审核。</p>
        <div className="workspace-choice-row">{['保守','稳健','进取'].map(v=><button key={v}
          className={state['strategy-selected-level']===v?'selected':''}
          onClick={()=>set('strategy-selected-level',v)}>{v}</button>)}</div>
        <Button variant="outline" onClick={()=>markSaved('经营方向草稿已保存')}>保存经营方向</Button>
      </Card></div></aside></div>}
    {tab==='预算与阶段'&&<div className="v4-strategy-list"><button className="v4-strategy-entry" onClick={()=>setEditing('预算与阶段')}><strong>预算与经营阶段</strong><span>月度让利预算 {String(state['strategy-budget-0']||'未设定')} 元 · {String(state['strategy-phase']||'未选择阶段')}</span><ArrowRight size={17}/></button></div>}
    {editing==='预算与阶段'&&<div className="v4-drawer-backdrop" onClick={()=>setEditing(null)}><aside className="v4-detail-drawer" role="dialog" aria-modal="true" aria-label="预算与阶段配置" onClick={e=>e.stopPropagation()}><div className="v4-drawer-heading"><h2>预算与阶段</h2><Button variant="ghost" onClick={()=>setEditing(null)}>关闭</Button></div><div className="workspace-grid two">
      <Card className="workspace-feature"><h2>让利预算</h2><p>价格、活动共用预算。没有真实记账回读。</p>
        {['月度让利预算（元）','月度广告预算（元）','首批进货上限（元）'].map((label,i)=>
          <label className="workspace-field" key={label}>{label}
            <TextInput type="number" min="0" value={String(state['strategy-budget-'+i]||'')}
              onChange={e=>set('strategy-budget-'+i,e.target.value)}/></label>)}
        <Button variant="primary" onClick={()=>markSaved('预算已保存')}>保存预算</Button></Card>
      <Card className="workspace-feature"><h2>经营阶段</h2><p>阶段与时间可随经营变化，当前仅记录本机选择。</p>
        <div className="workspace-choice-row">{['准备','验证','增长','稳态'].map(x=><button key={x}
          className={state['strategy-phase']===x?'selected':''} onClick={()=>set('strategy-phase',x)}>{x}</button>)}</div>
        <Button variant="outline" onClick={()=>markSaved('阶段草稿已保存')}>保存阶段</Button></Card></div></aside></div>}
    {tab==='自动化'&&<div className="workspace-column">
      <Card className="workspace-alert"><LockKeyhole size={20}/><div><strong>自动化尚未生效</strong>
        <p>系统准备方案和真实自动执行尚未开放。调整下方选择只保存本机草稿，不会启动计划任务。</p></div></Card>
      <Card className="workspace-feature"><h2>系统可以自动做到哪一步</h2>
        {[
          ['全部待审批','任何会修改商品或店铺的动作都先给你看'],
          ['按规则自动执行','仅在真实服务端经过授权、规则和审计后才可执行（目前不可用）'],
        ].map(([name,desc])=><label className="workspace-radio-row" key={name}>
          <input type="radio" name="automation-mode" disabled={name!=='全部待审批'}
            checked={name==='全部待审批'} readOnly/>
          <span><strong>{name}</strong><small>{desc}</small></span></label>)}
        <label className="workspace-field">每天自动执行上限（演示）
          <TextInput type="number" min="0" max="20" value={String(state['automation-limit']??20)}
            onChange={e=>set('automation-limit',e.target.value)}/></label>
        <Button variant="primary" onClick={()=>markSaved('自动化草稿已保存')}>保存设置（不会执行）</Button>
      </Card></div>}
    {tab==='周报'&&<Card className="workspace-feature"><h2>本周经营回顾 · 原型样例</h2>
      <p>历史演示里处理过 5 条事项，准备过 6 个方案。新工程没有线上完整周报数据源。</p>
      <div className="workspace-statrow"><span><BarChart3 size={17}/> 模拟事项 5</span><span>模拟方案 6</span>
        <span><Clock3 size={17}/> 未连接定时生成</span></div>
      <Button variant="outline" onClick={()=>navigate('/todo')}>查看待办记录</Button></Card>}
    {saved&&<p className="workspace-confirmation" role="status"><CheckCircle2 size={16}/>{saved}</p>}
  </main>;
}
