/* A deliberately local demo protocol. No model, merchant API or background job. */
export type ChatRole = 'user' | 'assistant';
export type ProposalState = 'ready' | 'rejected' | 'simulated';
export type ChatAttachment = { name: string; size: number; type: string };
export type ChatProposal = {
  type: 'price' | 'stock';
  sku: string;
  before: string;
  after: string;
  impact: string;
  reversible: string;
  status: ProposalState;
};
export type ChatMessage = {
  id: string;
  role: ChatRole;
  text: string;
  time: number;
  attachments?: ChatAttachment[];
  proposal?: ChatProposal;
  suggestions?: string[];
};
export type ChatThread = {
  id: string;
  title: string;
  updatedAt: number;
  messages: ChatMessage[];
};
export const CHAT_STORAGE_KEY = 'orbita-rebuild-demo-chat-v1';
export const CHAT_CURRENT_KEY = 'orbita-rebuild-current-chat-v1';

const defaults = ['我的商品现在都什么情况','CZ7271 采购价 25，该定多少',
  '把 CZ7271 的价格改到 600','现在有哪些活动能报','商品突然没流量怎么排查'];

export const CHAT_PROMPTS = defaults;
export const CHAT_MAX_TEXT = 4000;
export const CHAT_MAX_THREADS = 30;
export const CHAT_MAX_MESSAGES = 80;
const textLimit = (s: string) => s.slice(0,CHAT_MAX_TEXT);
export const makeId = () => crypto.randomUUID();
export function readChatThreads(): ChatThread[] {
  try {
    const raw: unknown = JSON.parse(localStorage.getItem(CHAT_STORAGE_KEY) || '[]');
    if (!Array.isArray(raw)) return [];
    return raw.slice(0,CHAT_MAX_THREADS).filter((thread: unknown): thread is ChatThread => {
      if (!thread || typeof thread !== 'object') return false;
      const item = thread as Partial<ChatThread>;
      return typeof item.id === 'string' && typeof item.title === 'string'
        && typeof item.updatedAt === 'number' && Array.isArray(item.messages)
        && item.messages.every(message => message && typeof message.text === 'string'
          && (message.role === 'user' || message.role === 'assistant'));
    }).map(thread => ({...thread,messages:thread.messages.slice(-CHAT_MAX_MESSAGES)}));
  } catch {return [];}
}
export function saveChatThreads(threads: ChatThread[]): boolean {
  try {
    localStorage.setItem(CHAT_STORAGE_KEY, JSON.stringify(threads.slice(0,CHAT_MAX_THREADS)
      .map(t=>({...t,messages:t.messages.slice(-CHAT_MAX_MESSAGES)}))));
    return true;
  } catch {return false;}
}
export function validateAttachment(file: {name:string;size:number;type:string}): string | null {
  const ext = (file.name.toLowerCase().match(/\.[^.]+$/)?.[0]||'');
  if (!['.png','.jpg','.jpeg','.webp','.gif','.xlsx','.xls','.json'].includes(ext))
    return '仅支持图片、Excel 表格与 JSON 文件';
  const sizeLimit = ext === '.json' ? 2 : 23;
  if (file.size > sizeLimit*1024*1024) return `该文件不能超过 ${sizeLimit} MB`;
  return null;
}
export function makeDemoResponse(input: string, attachments: ChatAttachment[]=[]): Pick<ChatMessage,'text'|'proposal'|'suggestions'> {
  const prompt = input.trim();
  const sku = prompt.match(/\b(CZ7271|DK-118|BX-021|NEW-07)\b/i)?.[1]?.toUpperCase();
  const action = /改价|改到|改为|调整.*价|价格改|售价改|补库存|改库存|库存改|上架.*件/;
  const amount = prompt.match(/(?:改到|改为|调整到|设置为|售价(?:是|为)?|补到|改成)\s*(\d{1,5})/);
  if (sku === 'CZ7271' && action.test(prompt) && amount && /价格|价|售价/.test(prompt)) {
    const value = Number(amount[1]);
    if (value < 1 || value > 99999) return {text:'价格不在演示范围内，请核对输入。'};
    const difference = value-690;
    return {
      text:'已根据本地演示数据准备改价方案。这里只能预览和记录模拟决定，不会提交到 Ozon。',
      proposal:{type:'price',sku,before:'690 RUB',after:value+' RUB',
        impact:`变化 ${difference>0?'+':''}${difference} RUB（演示保本参考值：512 RUB；请另行核实）`,
        reversible:'可再次提交反向调整；演示环境不会执行实际操作',status:'ready'},
      suggestions:['看现在线上状态','还有别的问题吗'],
    };
  }
  if (sku === 'DK-118' && /库存|补货/.test(prompt) && amount) {
    return {
      text:'已准备本地库存修改预览。请核对库存账本与真实可售数量，演示不会提交操作。',
      proposal:{type:'stock',sku,before:'0 件',after:amount[1]+' 件',
        impact:'模拟恢复可售库存；可能涉及超卖风险',reversible:'可以重新修改库存；演示不会实际更新',status:'ready'},
      suggestions:['我的商品现在都什么情况'],
    };
  }
  if (action.test(prompt) && /改到|改为|调整到|设置为|改成/.test(prompt)) {
    return {text:'当前演示仅提供 CZ7271 改价和 DK-118 库存调整的本地预览。其他商品不会生成真实变更计划；可到商品页面继续查看静态演示。',
      suggestions:['我的商品现在都什么情况']};
  }
  if (attachments.length) return {
    text:`已在本地附加 ${attachments.length} 个文件名。此 React 演示暂不读取文件内容，也不会上传到服务器。请勿把这条回复当作文件分析结果。`,
    suggestions:['我的商品现在都什么情况'],
  };
  if (/商品|库存|CZ7271|DK-118|BX-021/.test(prompt)) return {
    text:'已读取本地演示店铺摘要：共 3 个商品，其中 1 个缺货、1 个价格需要关注。CZ7271 演示售价 690 RUB，保本参考价 512 RUB；BX-021 可售库存为 0。所有数字为固定演示数据，未连接线上店铺。',
    suggestions:['哪些商品今天最该处理','把 CZ7271 的价格改到 600'],
  };
  if (/活动|报活动|广告/.test(prompt)) return {
    text:'演示提醒显示 QHBB01-2 被自动加入活动 1977747，折后价低于保本参考价 12%。可以在增长或待办页查看；这是静态样例，不是最新平台数据。',
    suggestions:['哪些商品今天最该处理'],
  };
  if (/发货|订单|货源/.test(prompt)) return {
    text:'演示数据中有 1 单待发，另有 NEW-07 的货源映射需要核对。请到订单页核实实际截止时间；当前无法查询或执行真实订单。',
    suggestions:['我的商品现在都什么情况'],
  };
  if (/自动|巡检|周复盘|月初|例行/.test(prompt)) return {
    text:'自动化演示尚未接入实际任务调度或店铺接口。可在待办中检查已有模拟审批，在设置中查看原版自动化演示；本回复没有启动任何任务。',
    suggestions:['我的商品现在都什么情况'],
  };
  return {
    text:'当前是 Orbita 本地演示聊天，没有连接真实 AI 模型或 Ozon API。可以体验商品概览、订单摘要、活动提醒和 CZ7271 改价预览；其他问题请使用保留的原版静态演示或等待后端集成。',
    suggestions:defaults.slice(0,2),
  };
}
export function makeChatExchange(input: string,attachments:ChatAttachment[]=[]): ChatMessage[] {
  const time = Date.now();
  return [
    {id:makeId(),role:'user',text:textLimit(input.trim()),time,attachments},
    {id:makeId(),role:'assistant',time:time+1,...makeDemoResponse(input,attachments)},
  ];
}
