export type ProductId = 'BX-021' | 'CZ7271' | 'HL-330';
export type ProductStatus = '在售' | '归档';
export type ProductKind = 'shortage' | 'price' | 'improve';
export type Product = {
  id: ProductId;
  russian: string;
  chinese: string;
  status: ProductStatus;
  price: number;
  stock: number;
  sales30: number;
  contentScore: number;
  issue: ProductKind;
  sources: string[];
  issues?: Array<'price'|'promotion'|'improve'>;
};
export type ProductDraft = Partial<Pick<Product, 'price' | 'stock'>>;
export type ProductChanges = Partial<Record<ProductId, ProductDraft>>;
export const PRODUCT_STORAGE_KEY = 'orbita-rebuild-demo-products-v1';

// Grounded in the recovered 2026-10-22 static products page.
export const PRODUCT_FIXTURES: Product[] = [
  { id:'BX-021', russian:'Органайзер', chinese:'收纳盒', status:'在售',
    price:690, stock:0, sales30:0, contentScore:75, issue:'shortage', sources:['Ozon','1688'] },
  { id:'CZ7271', russian:'Кроссовки мужские', chinese:'男士运动鞋', status:'在售',
    price:690, stock:12, sales30:0, contentScore:80, issue:'price', sources:['Ozon','1688'] },
  { id:'HL-330', russian:'Лампа настольная', chinese:'台灯', status:'在售',
    price:690, stock:12, sales30:44, contentScore:85, issue:'improve', sources:['Ozon'] },
];
// Fixture scores for two products are illustrative, rather than verified
// against backend/API data; do not surface them as live platform results.
export const ISSUE_LABELS:Record<ProductKind,string>={
  shortage:'缺货',price:'价格偏高',improve:'可提升',
};
export function readProductChanges():ProductChanges {
  try {
    const stored:unknown=JSON.parse(localStorage.getItem(PRODUCT_STORAGE_KEY)||'{}');
    if (!stored || typeof stored!=='object' || Array.isArray(stored)) return {};
    const result:ProductChanges={};
    for(const item of PRODUCT_FIXTURES){
      const record=(stored as Record<string,unknown>)[item.id];
      if(!record || typeof record!=='object')continue;
      const draft=record as Record<string,unknown>;
      const next:ProductDraft={};
      if(typeof draft.price==='number' && Number.isInteger(draft.price) && draft.price>=1 && draft.price<=99999)next.price=draft.price;
      if(typeof draft.stock==='number' && Number.isInteger(draft.stock) && draft.stock>=0 && draft.stock<=99999)next.stock=draft.stock;
      if(Object.keys(next).length)result[item.id]=next;
    }
    return result;
  } catch {return {};}
}
export function writeProductChanges(changes:ProductChanges){
  try {localStorage.setItem(PRODUCT_STORAGE_KEY,JSON.stringify(changes));}catch{/* no storage */}
}
export function visibleProducts(changes:ProductChanges):Product[]{
  return PRODUCT_FIXTURES.map(p=>({...p,...changes[p.id]}));
}
export function productIssue(p:Product):ProductKind{
  if(p.stock===0)return 'shortage';
  if(p.id==='CZ7271' && p.price>=690)return 'price';
  return 'improve';
}
/** Independent issue flags: a product may have pricing, promotion and content issues together. */
export function productIssues(p:Product):string[]{
  const issues:string[]=[];
  if(p.stock===0)issues.push('缺货');
  if(p.issues?.includes('price') || productIssue(p)==='price')issues.push('价格偏高');
  if(p.issues?.includes('promotion'))issues.push('活动异常');
  if(p.contentScore<70)issues.push('内容分低');
  else if(p.contentScore<90 || p.issues?.includes('improve'))issues.push('可提升');
  return issues;
}
export function productFilter(p:Product,filter:string):boolean{
  switch(filter){
    case '全部商品':return true;
    case '货源':return p.sources.length>0;
    case '定价资料':return p.id!=='HL-330';
    case '库存':return true;
    case '缺货':return p.stock===0;
    case '价格偏高':case '内容分低':case '活动异常':case '可提升':return productIssues(p).includes(filter);
    case '已归档':return p.status==='归档';
    case '健康':return productIssues(p).length===0;
    default:return true;
  }
}
export function productCounts(changes:ProductChanges){
  const products=visibleProducts(changes);
  return {
    all:products.length,
    shortage:products.filter(x=>productIssue(x)==='shortage').length,
    price:products.filter(x=>productIssue(x)==='price').length,
    improvements:products.length,
  };
}
export function validateProductEdit(field:'price'|'stock',raw:string){
  if(!/^\d+$/.test(raw.trim()))return null;
  const n=Number(raw.trim());
  if(!Number.isSafeInteger(n)||n>99999||n<(field==='price'?1:0))return null;
  return n;
}
