import { useState } from 'react';
import {
  ArrowRight, Bell, CheckCircle2, ChevronDown, CircleAlert,
  ClipboardCheck, MessageCircle, Package, RefreshCw, Send, ShieldCheck, Truck,
} from 'lucide-react';
import { Badge, Button, Card } from '../components/ui';
import { productCounts, type ProductChanges } from '../domain/products';
import {
  APPROVALS, NOTICES, countWorkTab, workTab, type WorkDecisions,
} from '../domain/work-items';

const onboarding = [
  { title:'连上 Ozon 店铺', description:'已连上', done:true },
  { title:'把店里的商品拉进来', description:'已有 3 个商品', done:true },
  { title:'录成本（采购价和打包尺寸）', description:'成本覆盖 3/3（100%）', done:true },
  { title:'接飞书提醒', description:'尚未接飞书群，有事只能来这里看', done:false, route:'/settings/notify' },
  { title:'连好 1688 和货代', description:'1688 和货代都连着', done:true },
  { title:'定经营方向', description:'尚未设定系统动作的上限约束', done:false, route:'/strategy' },
];
const health = [
  { title:'价格', score:67, caption:'3 个里 1 个红档被降权 · 去改价' },
  { title:'库存', score:67, caption:'1 个缺货 · 去补货' },
  { title:'内容', score:80, caption:'平均 80 分' },
  { title:'活动', score:100, caption:'1 个被自动加入，价格都在' },
  { title:'发货', score:100, caption:'1 单已发出' },
  { title:'动销', score:33, caption:'1/3 个商品近 30 天出过单' },
];
export default function OverviewPage({
  navigate, decisions,productChanges
}: {
  navigate:(route:string)=>void;decisions:WorkDecisions;productChanges:ProductChanges
}){
  const [showSteps,setShowSteps]=useState(false);
  const [lastChecked,setLastChecked]=useState(new Date());
  const pending=countWorkTab('pending',decisions);
  const attention=countWorkTab('attention',decisions);
  const pendingItem=APPROVALS.find(x=>workTab(x,decisions)==='pending');
  const mainNotice=NOTICES.find(x=>workTab(x,decisions)==='attention');
  const productStats=productCounts(productChanges);
  const now=lastChecked.toLocaleString('zh-CN',{
    timeZone:'Asia/Shanghai',month:'long',day:'numeric',weekday:'long',
    hour:'2-digit',minute:'2-digit',hour12:false,
  });

  const statCards=[
    { title:'待审批',value:pending,summary: pendingItem ? '最急：'+pendingItem.sku+' '+pendingItem.label : '暂无需要审批的方案',
      hint:'需要明确确认的动作',icon:ClipboardCheck,route:'/todo' },
    { title:'需关注',value:attention,summary:mainNotice?'紧急：'+mainNotice.sku+' '+mainNotice.summary:'当前没有需要关注的提醒',
      hint:'紧急和今天要看的提醒',icon:Bell,route:'/todo' },
    { title:'今日待发',value:1,summary:'0135-8821 · 截止时间请在订单页核实',
      hint:'已逾期或截止将近的订单',icon:Truck,route:'/orders?tab=due' },
    { title:'商品待处理',value:productStats.price+productStats.shortage,
      summary:'价格红区 '+productStats.price+' · 缺货 '+productStats.shortage,
      hint:'共 '+productStats.all+' 个本地演示商品',icon:Package,route:'/products' },
  ];
  return <main className="native-overview">
    <header className="overview-heading">
      <div><h1>概览</h1>
        <p>{now}（北京） · 测试店 · 本地演示数据</p>
      </div>
      <div className="overview-toolbar">
        <Button variant="outline" onClick={()=>navigate('/chat')}><MessageCircle size={16}/> 整页对话</Button>
        <Button variant="outline" onClick={()=>setLastChecked(new Date())}><RefreshCw size={16}/> 刷新</Button>
      </div>
    </header>
    <section className="overview-brief" aria-labelledby="overview-brief-title">
      <div className="overview-section-top">
        <div><h2 id="overview-brief-title">今日经营重点</h2></div>
      </div>
      <div className="overview-kpis">{statCards.map(s=>{
        const Icon=s.icon;return <button className="overview-kpi" key={s.title} onClick={()=>navigate(s.route)}>
          <span className="overview-kpi-label"><Icon size={17}/>{s.title}<ArrowRight size={15}/></span>
          <strong className="overview-kpi-value">{s.value}</strong>
          <span className="overview-kpi-summary">{s.summary}</span>
        </button>})}</div>
    </section>
    <section className="overview-onboarding" aria-label="新店上手">
      <button className="overview-steps-heading" onClick={()=>setShowSteps(x=>!x)} aria-expanded={showSteps}>
        <span><ShieldCheck size={19}/> 新店上手 <Badge>还差 2 步</Badge></span>
        <ChevronDown size={19} className={!showSteps?'closed':''}/>
      </button>
      {showSteps&&<div className="overview-steps">
        {onboarding.map(step=><div className="overview-step" key={step.title}>
          <CheckCircle2 size={18} className={step.done?'done':'incomplete'} />
          <div><strong>{step.title}</strong><small>{step.description}</small></div>
          {!step.done&&<Button variant="outline" size="sm" onClick={()=>navigate(step.route!)}>去处理 <ArrowRight size={14}/></Button>}
        </div>)}
      </div>}
    </section>
    <section className="overview-actions" aria-labelledby="overview-actions-title">
      <div className="overview-section-top"><h2 id="overview-actions-title">先做这三件</h2>
        <Button variant="ghost" onClick={()=>navigate('/todo')}>查看全部待办 <ArrowRight size={16}/></Button>
      </div>
      <div className="overview-action-grid">
        <Card className="overview-action-card">
          <Badge>{pendingItem?.label||'审批'}</Badge>
          <h3>{pendingItem?.sku||'待审批已清空'}</h3>
          <p>{pendingItem?.summary||'目前没有新的审批方案。'}</p>
          <Button variant="primary" onClick={()=>navigate('/todo')}><ClipboardCheck size={16}/> {pendingItem?'查看预览并审批':'查看待办'}</Button>
        </Card>
        <Card className="overview-action-card">
          <Badge>需关注</Badge>
          <h3>{mainNotice?.sku||'提醒已处理'}</h3>
          <p>{mainNotice?.summary||'当前没有高优先级提醒。'}</p>
          <Button variant="outline" onClick={()=>navigate('/todo')}>查看并处理 <ArrowRight size={16}/></Button>
        </Card>
        <Card className="overview-action-card">
          <Badge>发货</Badge><h3>NEW-07</h3>
          <p>0135-8834 · 缺货源映射；请核实订单截止时间。</p>
          <Button variant="outline" onClick={()=>navigate('/orders?tab=due')}>指定货源 <ArrowRight size={16}/></Button>
        </Card>
      </div>
    </section>
    <section className="overview-health" aria-labelledby="overview-health-title">
      <div className="overview-section-top"><div><h2 id="overview-health-title">店铺经营健康度</h2>
        <p>各维度满分 100，80 为参考健康线。</p></div>
        <Button variant="ghost" onClick={()=>navigate('/strategy')}>经营策略 <ArrowRight size={16}/></Button>
      </div>
      <div className="overview-health-grid">{health.map(s=><div className="overview-health-item" key={s.title}>
        <div><strong>{s.title}</strong><span>{s.score}</span></div>
        <div className="overview-health-track"><span style={{width:s.score+'%'}} /></div>
        <small>{s.caption}</small>
      </div>)}</div>
    </section>
    <div className="overview-questions">
      <span><CircleAlert size={16}/> 有问题想问 Orbita？</span>
      <Button variant="outline" onClick={()=>navigate('/chat')}>打开完整对话 <Send size={16}/></Button>
    </div>
  </main>;
}
