export const FULFILLMENT_STEPS=['下单','采购','到仓','贴单','交运','在途','签收'] as const;
export const ORDER_TABS:{id:OrderTab;title:string}[]=[
  {id:'need',title:'需要你'},{id:'today',title:'今天要发'},
  {id:'running',title:'系统在办'},{id:'transit',title:'在途'},
  {id:'completed',title:'已完成'},
];
export function orderTabItems(tab:OrderTab):Order[]{
  switch(tab){
    case 'need':
    case 'today':return ORDER_FIXTURES.filter(o=>o.status==='needs-user');
    case 'completed':return ORDER_FIXTURES.filter(o=>o.status==='completed');
    case 'transit':
    case 'running':return [];
  }
}
