import { useState } from 'react';
import { ArrowLeft, Check, ChevronDown, LayoutGrid, Search, Settings, Sparkles } from 'lucide-react';
import { Avatar, Badge, Button, Card, IconButton, Textarea, TextInput, ToolButton } from '../components/ui';

const SWATCHES = [
  { label: '主文字', variable: '--text-primary' },
  { label: '次级文字', variable: '--text-secondary' },
  { label: '主背景', variable: '--page-bg' },
  { label: '交互悬停', variable: '--surface-hover' },
  { label: '默认边框', variable: '--border-default' },
  { label: '品牌强调', variable: '--color-accent' },
  { label: '成功状态', variable: '--color-success' },
  { label: '危险状态', variable: '--color-danger' },
] as const;
const SPACES = ['--space-1','--space-2','--space-3','--space-4','--space-6','--space-8'] as const;

export default function DesignSystemPage({ navigate }: { navigate: (page: string) => void }) {
  const [clicks, setClicks] = useState(0);
  const [name, setName] = useState('');
  const [message, setMessage] = useState('');
  return <main className="component-catalog">
    <header className="catalog-header">
      <button className="catalog-back" onClick={() => navigate('/settings/appearance')}>
        <ArrowLeft size={17} aria-hidden="true" /> 返回外观设置
      </button>
      <p className="settings-eyebrow">ORBITA DESIGN SYSTEM · v1</p>
      <h1>基础组件与设计变量</h1>
      <p>所有示例都直接引用共享 Token，并使用实际可复用的 React 组件。这里是开发验收工作台，不是线上业务页面。</p>
    </header>
    <div className="catalog-grid">
      <Card className="catalog-panel">
        <h2><LayoutGrid size={18} /> 色彩语义</h2>
        <p className="catalog-subtitle">业务页面使用语义变量，而不是重复填写十六进制色值。</p>
        <div className="catalog-colors">{SWATCHES.map(item => <div className="catalog-color" key={item.variable}>
          <span className="catalog-swatch" style={{ backgroundColor: `var(${item.variable})` }} />
          <span><strong>{item.label}</strong><code>{item.variable}</code></span>
        </div>)}</div>
      </Card>
      <Card className="catalog-panel">
        <h2><Sparkles size={18} /> 间距与圆角</h2>
        <p className="catalog-subtitle">统一 4px 基础间距；导航统一 40px 行高和 4px 间隔。</p>
        <div className="catalog-space-list">{SPACES.map(token => <div className="catalog-space" key={token}>
          <code>{token}</code><span style={{ width: `var(${token})` }}/></div>)}</div>
        <div className="catalog-radius-row">
          <div className="catalog-radius-sm">小圆角</div>
          <div className="catalog-radius-lg">卡片圆角</div>
          <div className="catalog-radius-pill">圆角胶囊</div>
        </div>
      </Card>
      <Card className="catalog-panel">
        <h2>按钮与反馈</h2>
        <p className="catalog-subtitle">尺寸、变体、焦点、禁用和点击反馈使用统一 Button。</p>
        <div className="catalog-controls">
          <Button variant="primary" onClick={() => setClicks(n => n + 1)}><Check size={16}/> 主按钮</Button>
          <Button variant="outline" onClick={() => setClicks(n => n + 1)}>描边按钮</Button>
          <Button variant="ghost" onClick={() => setClicks(n => n + 1)}>文字按钮</Button>
          <IconButton aria-label="打开设置示例" onClick={() => setClicks(n => n + 1)}><Settings size={19}/></IconButton>
          <Button disabled>不可操作</Button>
        </div>
        <output aria-live="polite" className="catalog-output">已触发 {clicks} 次示例操作</output>
        <div className="catalog-controls"><Badge>默认状态</Badge><Badge>待处理</Badge><Avatar name="LLYing" />
          <ToolButton label="示例提示" onClick={() => setClicks(n => n + 1)}><ChevronDown size={20}/></ToolButton></div>
      </Card>
      <Card className="catalog-panel">
        <h2>输入与表单</h2>
        <p className="catalog-subtitle">展示完整的受控输入态、焦点态以及文本区域。</p>
        <label className="catalog-label" htmlFor="catalog-input">输入名称</label>
        <div className="catalog-input-wrap"><Search size={17} />
          <TextInput id="catalog-input" value={name} onChange={e => setName(e.target.value)}
            placeholder="输入内容验证组件状态" />
        </div>
        <label className="catalog-label" htmlFor="catalog-textarea">多行描述</label>
        <Textarea id="catalog-textarea" value={message} onChange={e => setMessage(e.target.value)}
          placeholder="输入说明…" rows={3} />
        <p className="catalog-output">输入：{name || '未填写'} · 文字：{message.length} 字</p>
      </Card>
    </div>
  </main>;
}
