import { ArrowRight, Check, Laptop2, Moon, Sun } from 'lucide-react';
import { Card, Badge, Button } from '../components/ui';
import { SettingsLayout } from './SettingsLayout';

export type ThemeMode = 'light' | 'dark' | 'system';

const APPEARANCE_OPTIONS: {
  value: ThemeMode; label: string; description: string; icon: typeof Sun
}[] = [
  { value: 'light', label: '浅色', description: '冷调蓝白 · 日间清爽', icon: Sun },
  { value: 'dark', label: '深色', description: '深空蓝黑 · 夜间护眼', icon: Moon },
  { value: 'system', label: '跟随系统', description: '随设备外观自动切换', icon: Laptop2 },
];

export default function AppearancePage({
  mode, resolvedTheme, onModeChange, navigate
}: {
  mode: ThemeMode;
  resolvedTheme: 'light' | 'dark';
  onModeChange: (next: ThemeMode) => void;
  navigate: (route: string) => void;
}) {
  return <SettingsLayout current="/settings/appearance" title="外观"
    description="选择界面主题，立即生效并记住偏好。" navigate={navigate}>
    <Card className="appearance-card">
      <div className="appearance-card-header">
        <div>
          <h3>主题模式</h3>
          <p>选择你习惯的视觉风格</p>
        </div>
        <Badge>当前：{mode === 'system' ? '跟随系统' : mode === 'dark' ? '深色' : '浅色'}</Badge>
      </div>
      <fieldset className="appearance-options" aria-label="界面主题">
        <legend className="sr-only">界面主题</legend>
        {APPEARANCE_OPTIONS.map(option => {
          const Icon = option.icon;
          return <label className={'appearance-option' + (mode === option.value ? ' selected' : '')}
            key={option.value}>
            <input type="radio" name="orbita-theme" value={option.value}
              checked={mode === option.value} onChange={() => onModeChange(option.value)} />
            <span className="appearance-option-icon"><Icon size={21} strokeWidth={1.8}/></span>
            <span className="appearance-option-info">
              <strong>{option.label}</strong>
              <small>{option.description}</small>
            </span>
            <span className="appearance-radio-indicator" aria-hidden="true">
              {mode === option.value && <Check size={13} strokeWidth={2.5} />}
            </span>
          </label>;
        })}
      </fieldset>
      <div className="appearance-help">
        {mode === 'system'
          ? <>正在跟随设备，当前显示为{resolvedTheme === 'dark' ? '深色' : '浅色'}模式。设备外观切换时将自动更新。</>
          : <>选择立即生效；侧边栏的模式按钮会同步更新，刷新页面后仍会记住。</>}
      </div>
      <div className="appearance-catalog-link">
        <Button variant="outline" onClick={() => navigate('/design-system')}>
          查看基础组件与设计变量 <ArrowRight size={16}/>
        </Button>
      </div>
    </Card>
  </SettingsLayout>;
}
