const suffix=(route:string)=>route.split('/').pop()?.split('?')[0]||'account';
export default function NativeSettingsPage({route,navigate}:{route:string;navigate:(path:string)=>void}){
  const id=suffix(route),config=settingConfig[id]||settingConfig.account;
  const [settings,setSettings]=useState<PrototypeSettings>(readPrototypeSettings);
  const [notice,setNotice]=useState('');
  useEffect(()=>{setNotice('')},[route]);
  function update(key:string,value:string|boolean|number){setSettings(v=>({...v,[key]:value}));setNotice('')}
  function persist(){
    if(id==='fulfillment'&&settings['ship-policy']!==undefined &&
      String(settings['ship-policy-reason']||'').trim().length<3){
      setNotice('请填写至少 3 字的策略修改理由');return;
    }
    setNotice(savePrototypeSettings(settings)?'本地设置草稿已保存。未提交到真实平台或账号。':'浏览器存储不可用，草稿未保存');
  }
  const editable=config.groups.some(g=>g.fields?.length);
  return <SettingsLayout title={config.title} description={config.intro}
    current={'/settings/'+id} navigate={navigate}>
    <div className="workspace-column">
      <Card className="workspace-alert"><CloudOff size={18}/><div><strong>原生界面 · 模拟配置</strong>
        <p>未连接认证、店铺或外部 API。此页仅保存非敏感的本地偏好；凭证、密码与 Cookie 不收集、不保存。</p></div></Card>
      {config.groups.map(group=><Card className="workspace-feature" key={group.title}>
        <div className="workspace-row"><h3>{group.title}</h3>
          {id==='switches'&&<Badge>只读</Badge>}</div>
        {group.intro&&<p className="workspace-paragraph">{group.intro}</p>}
        {group.fields?.map(field=>{
          const value=settings[field.key]??field.default??(field.kind==='check'?false:'');
          return <label className={'workspace-field '+(field.kind==='check'?'workspace-check':'')} key={field.key}>
            {field.kind==='check'
              ? <><input type="checkbox" checked={Boolean(value)} onChange={e=>update(field.key,e.target.checked)}/>{field.label}</>
              : <><span>{field.label}</span>
                {field.kind==='select'
                  ? <select value={String(value)} onChange={e=>update(field.key,e.target.value)}>
                    {field.options?.map(option=><option key={option}>{option}</option>)}</select>
                  : field.kind==='textarea'
                  ? <textarea value={String(value)} onChange={e=>update(field.key,e.target.value)}/>
                  : <TextInput type={field.kind==='number'?'number':'text'} min={field.kind==='number'?'0':undefined}
                    value={String(value)} onChange={e=>update(field.key,e.target.value)}/>}</>}
            {field.desc&&<small>{field.desc}</small>}
          </label>;
        })}
        {group.links?.map(link=><Button variant="outline" size="sm" key={link.route}
          onClick={()=>navigate(link.route)}>{link.label} <ArrowRight size={15}/></Button>)}
      </Card>)}
      {editable&&<div className="workspace-actions"><Button variant="primary" onClick={persist}>
        <CheckCircle2 size={17}/> 保存本地配置</Button></div>}
      {notice&&<p role="status" className="workspace-confirmation">{notice}</p>}
      {['account','shops','scrape'].includes(id)&&<Card><h3><LockKeyhole size={18}/> 账号与凭证安全</h3>
        <p>密码修改、远程注销、API Key 上传和 Cookie 验证均需服务端认证接口。当前界面不会假装操作成功。</p></Card>}
    </div>
  </SettingsLayout>;
}
