import {useEffect,useState} from 'react';
import {
  ArrowRight, ChevronDown, ChevronUp, CircleAlert, Clock3, ExternalLink,
  PackageCheck, RefreshCw, Search, ShieldAlert, Truck,
} from 'lucide-react';
import {Badge,Button,Card,TextInput} from '../components/ui';
import {FULFILLMENT_STEPS,ORDER_FIXTURES,ORDER_TABS,orderTabItems,type Order,type OrderTab} from '../domain/orders';

function OrderRow({order,expanded,onToggle,navigate}:{
  order:Order;expanded:boolean;onToggle:()=>void;navigate:(route:string)=>void
}){
  return <Card className="order-card">
    <div className="order-card-header">
      <div><div className="order-id-line"><strong>{order.id}</strong>
        <Badge>{order.status==='completed'?'已签收（演示）':'需要你核对'}</Badge></div>
        <p>{order.placed} 下单 · {order.deadline?order.deadline+' 前要发出（原版演示）':'Ozon：已签收（原版演示）'}</p>
      </div>
      <Button variant="ghost" size="sm" aria-expanded={expanded}
        aria-label={(expanded?'收起 ':'展开 ')+order.id+' 明细'} onClick={onToggle}>
        详情 {expanded?<ChevronUp size={17}/>:<ChevronDown size={17}/>}</Button>
    </div>
    <div className="order-product-line">
      <span className="order-thumbnail"><Truck size={22}/></span>
      <div><strong>{order.title}{order.qty>1?' ×'+order.qty:''}</strong><small>{order.sku}</small></div>
      <span>{order.price.toLocaleString('en-US')} ₽ <small>挂牌价</small></span>
    </div>
    <p className="order-progress-note">{order.progress}</p>
    <div className="order-steps" aria-label={'订单 '+order.id+' 发货阶段'}>
      {FULFILLMENT_STEPS.map((step,i)=><div key={step} className={'order-step '+(i<=order.fulfillmentStep?'reached':'')}>
        <span className="order-step-mark" aria-hidden="true"/><small>{step}</small></div>)}
    </div>
    {expanded&&<div className="v4-drawer-backdrop" onClick={onToggle}><aside role="dialog" aria-modal="true" aria-label={order.id+' 订单详情'} className="v4-detail-drawer" onClick={e=>e.stopPropagation()}>
      <div className="v4-drawer-heading"><h2>{order.id} · 订单详情</h2><Button variant="ghost" onClick={onToggle}>关闭</Button></div><section className="order-expanded">
      <h3>订单进度与核对</h3>
      <div className="order-detail-grid">
        <div><small>订单号</small><strong>{order.id}</strong></div>
        <div><small>商品货号</small><strong>{order.sku}</strong></div>
        <div><small>原型记录的截止时间</small><strong>{order.deadline||'已完成'}</strong></div>
        <div><small>当前演示进度</small><strong>{FULFILLMENT_STEPS[order.fulfillmentStep]}</strong></div>
      </div>
      <p className="order-warning"><CircleAlert size={16}/>{order.note}</p>
      <div className="order-expanded-actions">
        <Button variant="outline" size="sm" onClick={()=>navigate('/settings/fulfillment')}>
          查看发货规则 <ExternalLink size={15}/></Button>
        <Button variant="outline" size="sm" onClick={()=>navigate('/products')}>查看商品 <ArrowRight size={15}/></Button>
      </div>
    </section></aside></div>}
  </Card>;
}
export default function OrdersPage({navigate,route}:{
  navigate:(route:string)=>void;route:string
}){
  const initial=new URLSearchParams(route.split('?')[1]||'').get('tab');
  const [tab,setTab]=useState<OrderTab>(initial==='due'?'today':(ORDER_TABS.some(x=>x.id===initial)?initial as OrderTab:'need'));
  const [query,setQuery]=useState('');
  const [expanded,setExpanded]=useState<string|null>(null);
  const [showGuide,setShowGuide]=useState(route.startsWith('/orders/fulfillment'));
  const [refreshed,setRefreshed]=useState<Date|null>(null);
  useEffect(()=>{if(!expanded)return;const close=(event:KeyboardEvent)=>{if(event.key==='Escape')setExpanded(null)};window.addEventListener('keydown',close);return()=>window.removeEventListener('keydown',close)},[expanded]);
  const visible=orderTabItems(tab).filter(o=>(o.id+' '+o.title+' '+o.sku).toLowerCase().includes(query.toLowerCase().trim()));
  return <main className="orders-page">
    <header className="orders-header">
      <div><h1>订单</h1>
        <p>1 单需要你 · 1 单今天要发 · 0 单系统在办（原版演示计数，并非实时）</p>
      </div>
      <div className="orders-header-actions">
        <Badge>自动发货：未开启</Badge>
        <Button variant="outline" onClick={()=>setRefreshed(new Date())}><RefreshCw size={16}/> 刷新</Button>
        <Button variant="outline" onClick={()=>navigate('/settings/fulfillment')}>发货规则</Button>
      </div>
    </header>
    {refreshed&&<p className="orders-refresh-note" role="status">本地页面已重新检查演示状态：
      {refreshed.toLocaleTimeString('zh-CN',{timeZone:'Asia/Shanghai',hour:'2-digit',minute:'2-digit'})}
      （北京）。没有获取线上数据。</p>}
    <nav className="orders-tabs ui-tab-list" aria-label="订单状态">
      {ORDER_TABS.map(x=><button key={x.id} className={'orders-tab'+(tab===x.id?' active':'')}
        aria-current={tab===x.id?'page':undefined} onClick={()=>{setTab(x.id);setExpanded(null)}}>
        {x.title}{orderTabItems(x.id).length>0&&<span>{orderTabItems(x.id).length}</span>}
      </button>)}
    </nav>
    <div className="orders-ownership">
      <div className="orders-ownership-icon"><ShieldAlert size={20}/></div>
      <div><strong>发货由你处理</strong>
        <p>自动发货未生效；请按订单提示处理，并检查发货规则与连接。</p></div>
      <Button variant="ghost" size="sm" onClick={()=>navigate('/strategy?tab=autonomy')}>托管范围 <ArrowRight size={15}/></Button>
    </div>
    <div className="orders-static-warning"><CircleAlert size={16}/>
      自动发货未开启：系统不会采购、报货代或发货，已同意的单也不会自动往下办；
      请在 Ozon 官方后台核对并完成真实履约。
    </div>
    {showGuide&&<Card className="orders-guide">
      <div><strong>发货进度已并进订单</strong>
        <p>每张单一行，办到哪一步就在同一行上显示。</p></div>
      <Button variant="ghost" size="sm" onClick={()=>setShowGuide(false)}>知道了，收起</Button>
    </Card>}
    <div className="orders-toolbar">
      <span>{tab==='completed'?'按最近更新排':'按截止最近排'} · {visible.length} 单</span>
      <label className="orders-search"><Search size={17}/>
        <TextInput aria-label="搜索订单" placeholder="搜单号 / 货号"
          value={query} onChange={e=>setQuery(e.target.value)}/></label>
    </div>
    <section className="orders-list" aria-label="订单列表">
      {visible.map(order=><OrderRow key={order.id} order={order} navigate={navigate}
        expanded={expanded===order.id} onToggle={()=>setExpanded(s=>s===order.id?null:order.id)}/>)}
      {!visible.length&&<Card className="orders-empty">
        <PackageCheck size={28}/><strong>{query?'没有匹配的订单':'当前分类暂时没有订单'}</strong>
        <p>本页使用恢复的静态演示数据，没有连接真实订单状态。</p>
        {query&&<Button variant="outline" onClick={()=>setQuery('')}>清除搜索</Button>}
      </Card>}
    </section>
    <footer className="orders-footer"><Clock3 size={16}/> 演示订单时间和状态为原版快照，不代表当前平台最新状态。
      <Button variant="ghost" size="sm" onClick={()=>navigate('/settings/fulfillment')}>查看发货规则 <ArrowRight size={15}/></Button>
    </footer>
  </main>;
}
