import type { ReactNode } from 'react';
import {
  Bell, Building2, CircleUserRound, Image, Link2, Megaphone,
  Palette, Settings2, ShieldCheck, SlidersHorizontal, Users
} from 'lucide-react';

type SettingRoute = { label: string; path: string; icon: typeof Palette };
type SettingGroup = { title: string; entries: SettingRoute[] };

export const SETTING_GROUPS: SettingGroup[] = [
  { title: '账号', entries: [
    { label: '我的信息', path: '/settings/account', icon: CircleUserRound },
    { label: '外观', path: '/settings/appearance', icon: Palette },
  ] },
  { title: '店铺', entries: [
    { label: '店铺连接', path: '/settings/shops', icon: Building2 },
    { label: '团队与权限', path: '/settings/team', icon: Users },
    { label: '商品图与视频', path: '/settings/media', icon: Image },
    { label: '消息提醒', path: '/settings/notify', icon: Bell },
    { label: '发货规则', path: '/settings/fulfillment', icon: Settings2 },
  ] },
  { title: '连接', entries: [
    { label: '外部账号', path: '/settings/connections', icon: Link2 },
    { label: '广告账户', path: '/settings/ads', icon: Megaphone },
    { label: '1688 登录态', path: '/settings/scrape', icon: Link2 },
  ] },
  { title: '系统', entries: [
    { label: '开关总览', path: '/settings/switches', icon: SlidersHorizontal },
    { label: '自动化', path: '/settings/automation', icon: Settings2 },
    { label: '经营策略', path: '/settings/strategy', icon: ShieldCheck },
  ] },
];

export function SettingsLayout({
  title, description, current, navigate, children
}: {
  title: string; description: string; current: string;
  navigate: (route: string) => void; children: ReactNode
}) {
  return <div className="native-settings">
    <aside className="settings-navigation" aria-label="设置分类">
      <h1>设置</h1>
      {SETTING_GROUPS.map(group => <section className="settings-nav-group" key={group.title}>
        <h2>{group.title}</h2>
        {group.entries.map(entry => {
          const Icon = entry.icon;
          const active = entry.path === current;
          return <button key={entry.path} onClick={() => navigate(entry.path)}
            className={'settings-nav-item' + (active ? ' is-active' : '')}
            aria-current={active ? 'page' : undefined}>
            <Icon size={18} strokeWidth={1.8} aria-hidden="true" />
            <span>{entry.label}</span>
          </button>;
        })}
      </section>)}
    </aside>
    <main className="settings-page">
      <header className="settings-header">
        <p className="settings-eyebrow">偏好设置</p>
        <h2>{title}</h2>
        <p>{description}</p>
      </header>
      {children}
    </main>
  </div>;
}
