import { useEffect, useMemo, useRef, useState } from 'react';
import type {Dispatch,SetStateAction} from 'react';
import {
  ArrowDownUp, ArrowRight, Check, ChevronDown, CircleAlert, ClipboardCheck,
  CloudOff, FileBox, Filter, Package, PackagePlus, RefreshCw, Search, Settings2,
  ShieldCheck, SlidersHorizontal, X,
} from 'lucide-react';
import { Badge, Button, Card, IconButton, TextInput } from '../components/ui';
import {
  ISSUE_LABELS, PRODUCT_FIXTURES, productCounts, productFilter, productIssue,
  productIssues, validateProductEdit, visibleProducts,
  type Product, type ProductChanges, type ProductId,
} from '../domain/products';

type DetailTab = '体检'|'改价'|'库存'|'排名模拟'|'货源'|'记录';
type EditPreview = { id: ProductId; field:'price'|'stock'; before:number; after:number };
const tabs:DetailTab[]=['体检','改价','库存','排名模拟','货源','记录'];
const filters=['全部商品','货源','定价资料','库存','缺货','价格偏高','内容分低','活动异常','可提升','已归档','健康'];
type SortField = 'id'|'price'|'stock'|'sales30';

export default function ProductsPage({navigate,changes,setChanges}:{
  navigate:(page:string)=>void;changes:ProductChanges;
  setChanges:Dispatch<SetStateAction<ProductChanges>>;
}){
  const [filter,setFilter]=useState('全部商品');
  const [search,setSearch]=useState('');
  const [sort,setSort]=useState<{field:SortField;desc:boolean}>({field:'id',desc:false});
  const [selected,setSelected]=useState<ProductId|null>(null);
  const [detailTab,setDetailTab]=useState<DetailTab>('体检');
  const [edit,setEdit]=useState<{field:'price'|'stock';value:string}|null>(null);
  const [preview,setPreview]=useState<EditPreview|null>(null);
  const [alert,setAlert]=useState('');
  const [onlySelected,setOnlySelected]=useState(false);
  const [selectedRows,setSelectedRows]=useState<ProductId[]>([]);
  const [viewMode,setViewMode]=useState<'table'|'cards'>('table');
  const [updated,setUpdated]=useState(()=>new Date());
  const panelRef=useRef<HTMLDivElement>(null);
  const lastFocus=useRef<HTMLElement|null>(null);
  const products=useMemo(()=>visibleProducts(changes),[changes]);
  const counts=useMemo(()=>productCounts(changes),[changes]);
  const current=products.find(p=>p.id===selected)||null;
  const visible=useMemo(()=>products.filter(p=>(!onlySelected||selectedRows.includes(p.id))
    &&productFilter(p,filter)
    &&((p.id+' '+p.chinese+' '+p.russian).toLowerCase().includes(search.toLowerCase().trim())))
    .sort((a,b)=>{
      const x=sort.field==='id'?a.id.localeCompare(b.id):a[sort.field]-b[sort.field];
      return sort.desc?-x:x;
    }),[products,filter,search,sort,onlySelected,selectedRows]);
  useEffect(()=>{if(current)panelRef.current?.focus()},[selected]);
  useEffect(()=>{
    if(!current)return;
    const fn=(e:KeyboardEvent)=>{
      if(e.key==='Escape'){if(preview)setPreview(null);else closeDetail()}
      if(e.key==='Tab' && panelRef.current){
        const items=[...panelRef.current.querySelectorAll<HTMLElement>(
          'button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),[tabindex="0"]'
        )].filter(el=>el.getClientRects().length>0);
        if(!items.length)return;
        const first=items[0],last=items[items.length-1];
        if(e.shiftKey && document.activeElement===first){e.preventDefault();last.focus()}
        else if(!e.shiftKey && document.activeElement===last){e.preventDefault();first.focus()}
      }
    };
    window.addEventListener('keydown',fn);return()=>window.removeEventListener('keydown',fn);
  },[current,preview]);
  function closeDetail(){setSelected(null);setEdit(null);setPreview(null);lastFocus.current?.focus()}
  function openDetail(id:ProductId,tab:DetailTab='体检'){
    lastFocus.current=document.activeElement instanceof HTMLElement?document.activeElement:null;
    setSelected(id);setDetailTab(tab);setEdit(null);setPreview(null);
  }
  function startEdit(p:Product,field:'price'|'stock'){
    openDetail(p.id,field==='price'?'改价':'库存');
    setEdit({field,value:String(p[field])});
  }
  function propose(p:Product,field:'price'|'stock',raw:string){
    const value=validateProductEdit(field,raw);
    if(value==null){setAlert(field==='price'?'请输入 1–99999 的整数售价':'请输入 0–99999 的整数库存');return}
    if(value===p[field]){setAlert('新旧数值相同，无需产生变更');return}
    setAlert('');
    setPreview({id:p.id,field,before:p[field],after:value});
  }
  function confirmPreview(){
    if(!preview)return;
    const {id,field,after}=preview;
    setChanges(prev=>({...prev,[id]:{...prev[id],[field]:after}}));
    setPreview(null);setEdit(null);
    setAlert('已记录本地模拟变更，未提交到 Ozon。刷新页面后仍会保留。');
    setUpdated(new Date());
  }
  function resetDemo(){
    if(!window.confirm('恢复原始 3 个演示商品的售价和库存？这不会影响真实店铺。'))return;
    setChanges({});setPreview(null);setEdit(null);setAlert('已恢复本地演示商品');setSelectedRows([]);setOnlySelected(false);
  }
  function toggleSort(field:SortField){setSort(v=>v.field===field?{field,desc:!v.desc}:{field,desc:false})}
  const countForFilter=(key:string)=>products.filter(p=>productFilter(p,key)).length;
  return <main className="products-page">
    <header className="products-top">
      <div><h1>商品</h1>
        <p>{counts.all} 个 · {products.filter(p=>productIssues(p).some(x=>x!=='可提升')).length} 个要处理 · {products.filter(p=>productIssues(p).length>0).length} 个可优化 · 平均内容分 {Math.round(products.reduce((s,p)=>s+p.contentScore,0)/products.length)}
          <span className="products-muted"> · 所有数字为本地演示</span></p>
      </div>
      <div className="products-actions">
        <Button variant="outline" onClick={()=>setAlert('当前未连接真实 Ozon API，无法核对实时状态。你可以使用原版静态演示进行流程对照。')}>
          <RefreshCw size={16}/> 跟 Ozon 核对
        </Button>
        <Button variant="primary" onClick={()=>navigate('/new-product')}>
          <PackagePlus size={16}/> 上新
        </Button>
      </div>
    </header>
    <div className="products-main-tabs ui-tab-list" role="tablist" aria-label="商品视图">
      {['全部商品','货源','定价资料','库存'].map(x=><button key={x} role="tab"
        aria-selected={filter===x} className={filter===x?'active':''} onClick={()=>setFilter(x)}>
        {x}{x==='货源'||x==='定价资料'?<small>{countForFilter(x)}</small>:null}
      </button>)}
    </div>
    <div className="products-filters ui-choice-row" role="group" aria-label="商品筛选">
      {filters.slice(4).map(x=><button key={x} className={'products-filter'+(filter===x?' active':'')}
        aria-pressed={filter===x} onClick={()=>setFilter(x)}>
        {x}<span>{countForFilter(x)}</span></button>)}
    </div>
    <section className="products-insight">
      <div className="products-insight-icon"><ShieldCheck size={19}/></div>
      <div><strong>自动监测中 · 人工处理</strong><p>检测到的问题会显示在这里。商品修改先预览，再记录本地模拟决定。</p></div>
      <Button variant="ghost" size="sm" onClick={()=>navigate('/strategy?tab=autonomy')}>托管设置 <ArrowRight size={15}/></Button>
    </section>
    {alert&&<div className="products-notice" role="status"><CircleAlert size={16}/>{alert}
      <IconButton aria-label="关闭提示" onClick={()=>setAlert('')}><X size={15}/></IconButton>
    </div>}
    <div className="products-list-toolbar">
      <label className="products-search"><Search size={17}/><TextInput value={search} onChange={e=>setSearch(e.target.value)}
        aria-label="搜索商品" placeholder="搜货号或名称"/></label>
      <label className="products-only-selected"><input type="checkbox" checked={onlySelected} onChange={e=>setOnlySelected(e.target.checked)}/>仅显示已选</label>
      <div className="products-view-switch" role="group" aria-label="显示方式"><Button size="sm" variant={viewMode==='table'?'primary':'outline'} onClick={()=>setViewMode('table')}>表格</Button><Button size="sm" variant={viewMode==='cards'?'primary':'outline'} onClick={()=>setViewMode('cards')}>卡片</Button></div>
      {selectedRows.length>0&&<Button variant="outline" size="sm" onClick={()=>setSelectedRows([])}>已选 {selectedRows.length} 项 · 清空</Button>}
      <span className="products-sync-time">销量更新于 {updated.toLocaleTimeString('zh-CN',{timeZone:'Asia/Shanghai',hour:'2-digit',minute:'2-digit',hour12:false})}（北京） · 演示数据</span>
      <Button variant="ghost" size="sm" onClick={resetDemo}>重置模拟</Button>
    </div>
    {viewMode==='cards'?<div className="products-card-grid" style={{display:'grid',gridTemplateColumns:'repeat(auto-fit,minmax(min(100%,260px),1fr))',gap:12,padding:16}}>{visible.map(p=><Card key={p.id} className="products-card">
      <label><input type="checkbox" aria-label={'选择 '+p.id} checked={selectedRows.includes(p.id)} onChange={e=>setSelectedRows(ids=>e.target.checked?[...ids,p.id]:ids.filter(id=>id!==p.id))}/> 选择</label>
      <button className="product-name" onClick={()=>openDetail(p.id)}><span className="product-thumb"><Package size={18}/></span><span><strong>{p.id}</strong><small>{p.chinese}</small></span></button>
      <p>{p.price} ₽ · 可售 {p.stock} · 30天销量 {p.sales30} · 内容分 {p.contentScore}</p>
      <div>{productIssues(p).map(issue=><Badge key={issue}>{issue}</Badge>)}</div>
      <Button variant="outline" size="sm" onClick={()=>openDetail(p.id)}>查看详情</Button>
    </Card>)}</div>:<div className="products-table-scroll">
      <table className="products-table">
        <thead><tr>
          <th className="products-checkcell"><input type="checkbox" aria-label="选择当前显示的商品"
            checked={visible.length>0&&visible.every(x=>selectedRows.includes(x.id))}
            onChange={e=>setSelectedRows(e.target.checked?[...new Set([...selectedRows,...visible.map(p=>p.id)])]:
              selectedRows.filter(id=>!visible.some(p=>p.id===id)))}/></th>
          <th><button onClick={()=>toggleSort('id')}>商品 <ArrowDownUp size={14}/></button></th>
          <th>状态</th>
          <th><button onClick={()=>toggleSort('price')}>售价 ₽ <ArrowDownUp size={14}/></button></th>
          <th><button onClick={()=>toggleSort('stock')}>可售 <ArrowDownUp size={14}/></button></th>
          <th><button onClick={()=>toggleSort('sales30')}>30 天卖 <ArrowDownUp size={14}/></button></th>
          <th>问题</th><th>操作</th>
        </tr></thead>
        <tbody>{visible.map(p=><tr key={p.id}>
          <td><input type="checkbox" aria-label={'选择 '+p.id} checked={selectedRows.includes(p.id)}
            onChange={e=>setSelectedRows(ids=>e.target.checked?[...ids,p.id]:ids.filter(id=>id!==p.id))}/></td>
          <td><button className="product-name" aria-label={'打开 '+p.id+' 的详情'} onClick={()=>openDetail(p.id)}>
            <span className="product-thumb"><Package size={18}/></span>
            <span><strong>{p.id}</strong><small>{p.russian} · {p.chinese}</small></span>
          </button></td>
          <td><Badge>{p.status}</Badge></td>
          <td><button className="product-inline-value" aria-label={'编辑 '+p.id+' 售价'}
            onClick={()=>startEdit(p,'price')}>{p.price}</button></td>
          <td><button className="product-inline-value" aria-label={'编辑 '+p.id+' 库存'}
            onClick={()=>startEdit(p,'stock')}>{p.stock}</button></td>
          <td>{p.sales30}</td>
          <td>{productIssues(p).map(issue=><button key={issue} className={'product-issue '+productIssue(p)} onClick={()=>openDetail(p.id,'体检')}>{issue}</button>)}{productIssues(p).length===0&&'健康'}</td>
          <td><Button size="sm" variant="outline" onClick={()=>openDetail(p.id)}>查看</Button></td>
        </tr>)}</tbody>
      </table>
      {!visible.length&&<div className="products-empty"><FileBox size={24}/>
        <strong>没有符合当前条件的商品</strong><p>试试其他筛选或货号。</p>
        <Button variant="outline" onClick={()=>{setFilter('全部商品');setSearch('');setOnlySelected(false)}}>重置筛选</Button>
      </div>}
    </div>}
    <p className="products-hint">演示商品数据：点击售价或库存 → 预览 → 确认模拟；点商品查看右侧详情。所有操作均不连接真实店铺。</p>
    {current&&<div className="product-panel-scrim" onPointerDown={closeDetail}>
      <div role="dialog" aria-label={current.id+' 商品详情与操作'} aria-modal="true"
        className="product-panel" ref={panelRef} tabIndex={-1}
        onPointerDown={e=>e.stopPropagation()}>
        <div className="product-panel-header">
          <div><p>商品详情与操作</p><h2>{current.id}</h2></div>
          <IconButton aria-label="关闭商品详情" onClick={closeDetail}><X size={20}/></IconButton>
        </div>
        <div className="product-summary">
          <div className="product-summary-picture"><Package size={30}/></div>
          <div><strong>{current.chinese}</strong><p>{current.russian}</p>
            <span>{current.price} ₽ · 可售 {current.stock} · 内容分（演示）{current.contentScore}</span>
          </div>
        </div>
        <div className="product-detail-tabs ui-tab-list" role="tablist" aria-label="商品详情模块">
          {tabs.map(t=><button role="tab" aria-selected={detailTab===t} key={t}
            className={detailTab===t?'active':''} onClick={()=>{setDetailTab(t);setEdit(null);setPreview(null)}}>{t}</button>)}
        </div>
        <div className="product-panel-body">
          {detailTab==='体检'&&<section className="product-diagnosis">
            <h3>体检报告</h3>{productIssues(current).map(issue=><Badge key={issue}>{issue}</Badge>)}
            <dl>
              <div><dt>价格指数</dt><dd>{productIssue(current)==='price'?'红档：偏高，平台会降权':'待核对实时平台价格'}</dd></div>
              <div><dt>可售库存</dt><dd>{current.stock} 件</dd></div>
              <div><dt>内容分</dt><dd>{current.contentScore}（演示）</dd></div>
              <div><dt>上架与审核</dt><dd>{current.status}</dd></div>
            </dl>
            <Button variant="outline" onClick={()=>setDetailTab(productIssue(current)==='shortage'?'库存':'改价')}>
              {productIssue(current)==='shortage'?'查看补库存':'查看改价'} <ArrowRight size={16}/></Button>
          </section>}
          {(detailTab==='改价'||detailTab==='库存')&&<section className="product-edit-section">
            <h3>{detailTab==='改价'?'调整商品售价':'调整可售库存'} · 本地模拟</h3>
            <p>先查看数值变更和影响，再由你明确确认。不会提交到 Ozon。</p>
            <label htmlFor="product-edit-input">{detailTab==='改价'?'新售价（RUB）':'新可售数量（件）'}</label>
            <div className="product-edit-row">
              <TextInput key={current.id+detailTab} id="product-edit-input"
                inputMode="numeric" value={edit?.field===(detailTab==='改价'?'price':'stock')?edit.value:
                  String(detailTab==='改价'?current.price:current.stock)}
                onChange={e=>setEdit({field:detailTab==='改价'?'price':'stock',value:e.target.value})}/>
              <Button variant="primary" onClick={()=>propose(current,detailTab==='改价'?'price':'stock',
                edit?.value??String(detailTab==='改价'?current.price:current.stock))}>预览更改</Button>
            </div>
            {preview&&preview.id===current.id&&<Card className="product-edit-preview">
              <h4>确认前核对</h4>
              <div><span>修改前</span><strong>{preview.before}</strong></div>
              <div><span>修改后</span><strong>{preview.after}</strong></div>
              <div><span>变化</span><strong>{preview.after-preview.before>0?'+':''}{preview.after-preview.before}</strong></div>
              <p><CloudOff size={15}/> 仅保存在本机演示中，不执行真实改价或库存操作。</p>
              <div className="product-preview-buttons">
                <Button variant="outline" onClick={()=>setPreview(null)}>取消</Button>
                <Button variant="primary" onClick={confirmPreview}><Check size={16}/> 确认模拟变更</Button>
              </div>
            </Card>}
          </section>}
          {detailTab==='排名模拟'&&<section className="product-placeholder-section">
            <SlidersHorizontal size={23}/><h3>排名模拟</h3>
            <p>排名模拟需要竞品、平台规则和真实价格历史；当前没有可信的数据源，不能输出虚构预测。</p>
            <Button variant="outline" onClick={()=>navigate('/strategy')}>查看经营规则</Button>
          </section>}
          {detailTab==='货源'&&<section className="product-sources">
            <h3>货源连接（演示）</h3><p>原版商品记录中的货源标签：</p>
            {current.sources.map(source=><Badge key={source}>{source}</Badge>)}
            <p>货源价格、采购状态与自动同步尚未连接真实系统。</p>
          </section>}
          {detailTab==='记录'&&<section className="product-sources">
            <h3>本地变更记录</h3>
            <p>当前保存的模拟售价：{current.price} RUB，可售：{current.stock} 件。</p>
            <p>这里只保存最终值，不冒充平台真实操作日志。</p>
            <Button variant="outline" size="sm" onClick={resetDemo}>恢复原始商品数据</Button>
          </section>}
        </div>
        <footer className="product-panel-footer">
          <Button variant="outline" onClick={()=>navigate('/chat')}>问这个商品 <ArrowRight size={15}/></Button>
          <span>演示数据 · 非实时</span>
        </footer>
      </div>
    </div>}
  </main>;
}
