import {useMemo,useState} from 'react';
import {ArrowUpRight,BookOpen,Search} from 'lucide-react';
import {Badge,Button,Card,TextInput} from '../components/ui';
const base='https://global-help.ozon.com/zh';
const sections:{name:string;links:[string,string][]}[]=[
  {name:'上架与商品卡片',links:[
    ['商品上传方法','/products/upload/upload-types'],['商品审核要求','/products/upload/moderation'],
    ['合并商品（多变体）','/products/upload/merging-products'],
    ['内容评级','/products/selling-pdp/content-rating'],['商品卡片填写示例','/products/selling-pdp/good-pdps'],
    ['媒体要求（图片/视频）','/products/requirements/media'],
    ['商品归档库','/products/upload/archive'],['上传与编辑限额','/products/upload/upload-limit']]},
  {name:'价格',links:[['价格管理','/prices/price-control'],['价格冻结','/prices/price-quarantine'],
    ['区域价格系数','/prices/regional-price'],['海关税费','/prices/customs-duties']]},
  {name:'物流与库存',links:[['库存管理','/fulfillment/stock'],['realFBS 卖家自配送','/fulfillment/rfbs'],
    ['FBP 半托管','/fulfillment/fbp'],['取消及退货处理','/fulfillment/fbp-rfbs-returns-cancellations']]},
  {name:'推广与增长',links:[['商品推广','/promotion/product-promotions'],['促销活动与折扣','/promotion/promotions'],
    ['Ozon 大促销','/promotion/big-promotions'],['Premium 订阅','/promotion/subscriptions'],
    ['外部流量分析','/promotion/traffic-analysis']]},
  {name:'规则与合规',links:[['内容发布政策','/products/requirements'],['卖家帮助中心','/']]},
];
const questions=[
  ['FBO 和 FBS 区别','FBO 是平台仓储履约的一类模式，FBS 一般由卖家管理库存并交给平台配送。具体可用模式、费用与时效请查 Ozon 官方帮助。'],
  ['价格指数是什么','价格指数与平台参考价格、竞争情况等有关；本地演示没有最新的公式和竞品数据，请以官方价格管理文档为准。'],
  ['主位是什么，Ozon 有没有 buy box','主位指消费者默认看到的商品选项；商品排序和展示逻辑可能随平台更新。此处不臆测最新算法。'],
  ['商品突然没流量怎么排查','优先核查上架审核、库存、价格指数、商品内容及营销设置，然后对照平台官方流量数据。'],
];
export default function KnowledgePage({navigate}:{navigate:(route:string)=>void}){
  const [search,setSearch]=useState('');
  const [answer,setAnswer]=useState<(typeof questions)[number]|null>(null);
  const filtered=useMemo(()=>sections.map(s=>({...s,links:s.links.filter(([name])=>name.toLowerCase().includes(search.toLowerCase()))}))
    .filter(s=>s.links.length||!search),[search]);
  return <main className="native-workspace">
    <header className="workspace-header"><div>
      <h1>知识库</h1><p>平台怎么算、怎么查、官方原文在哪。引用优先，避免无来源的猜测。</p></div>
      <a className="workspace-external" href={base} target="_blank" rel="noopener noreferrer">
        官方卖家知识库（中文） <ArrowUpRight size={16}/></a></header>
    <section className="knowledge-tools"><div className="workspace-row"><h2>常见问题</h2>
      <label className="workspace-search"><Search size={17}/><TextInput aria-label="搜索官方文档" placeholder="搜索官方文档" value={search}
        onChange={e=>setSearch(e.target.value)}/></label></div>
      <div className="workspace-choice-row ui-choice-row">{questions.map(q=>
        <button key={q[0]} onClick={()=>setAnswer(q)} className={answer?.[0]===q[0]?'selected':''}>{q[0]}</button>)}</div>
      {answer&&<div className="workspace-answer" role="status"><strong>{answer[0]}</strong>
        <p>{answer[1]}</p><Badge>本地整理 · 请查官方原文</Badge>
        <Button variant="outline" size="sm" onClick={()=>navigate('/chat')}>在对话中继续提问</Button></div>}
    </section>
    <div className="workspace-row"><h2>官方原文</h2></div>
    <div className="workspace-grid knowledge-categories">{filtered.map(section=><Card key={section.name} className="workspace-feature">
      <h2>{section.name}</h2><div className="workspace-links">{section.links.map(([title,path])=>
        <a key={title} target="_blank" rel="noopener noreferrer" href={base+path}>{title}<ArrowUpRight size={16}/></a>)}</div>
    </Card>)}</div>
    {!filtered.length&&<Card className="workspace-empty">没有找到相关官方文档。请更换关键词。</Card>}
    <p className="workspace-footnote">这些链接是从原始 Orbita 演示页恢复的 Ozon 官方中文帮助中心路径，未实时校验所有链接当前是否可用。</p>
  </main>;
}
