/** Local-only prototype settings. No credentials or API tokens are persisted. */
export type PrototypeSettings = Record<string,string|boolean|number>;
const KEY='orbita-native-settings-v1';
const credentialKey = /(apikey|api-key|cookie|password|passwd|secret|webhook|access.?token|refresh.?token|private.?key|client.?id|client.?secret)/i;
function safeSettings(v:Record<string,unknown>):PrototypeSettings{
  const cleaned:PrototypeSettings={};
  for(const [k,value] of Object.entries(v)){
    if(!/^[a-z][a-z\d-]{0,80}$/i.test(k)||credentialKey.test(k))continue;
    if(typeof value==='boolean'||typeof value==='number'&&Number.isFinite(value))cleaned[k]=value;
    else if(typeof value==='string')cleaned[k]=value.slice(0,500);
  }
  return cleaned;
}
export function readPrototypeSettings():PrototypeSettings {
  try {
    const v:unknown=JSON.parse(localStorage.getItem(KEY)||'{}');
    if(!v||typeof v!=='object'||Array.isArray(v))return {};
    return safeSettings(v as Record<string,unknown>);
  }catch{return {}}
}
export function savePrototypeSettings(v:PrototypeSettings):boolean {
  try{localStorage.setItem(KEY,JSON.stringify(safeSettings(v)));return true}catch{return false}
}
export const SITE_ROUTES=[
  '/','/chat','/todo','/orders','/orders/fulfillment','/products',
  '/growth','/growth/promotions','/strategy','/kb',
  '/settings/account','/settings/appearance','/settings/shops','/settings/team',
  '/settings/media','/settings/notify','/settings/ads','/settings/connections',
  '/settings/automation','/settings/scrape','/settings/switches',
  '/settings/strategy','/settings/fulfillment',
  '/more','/operate','/queue','/catalog','/control-tower','/brief','/activate',
  '/site','/site/autopilot','/forgot-password','/reset-password',
  '/legal/privacy','/legal/terms','/prototype/index','/prototype/guide','/404','/_not-found',
  '/design-system','/products-legacy','/orders-legacy','/chat-legacy',
  '/new-product',
] as const;
export function resolveNativeRoute(path:string):string{
  const key=path.split('?')[0].replace(/\.html$/,'');
  if(key==='/overview'||key==='/index')return '/';
  if(['/operate','/catalog','/control-tower'].includes(key))return '/products';
  if(key==='/queue')return '/todo';
  if(key==='/activate')return '/';
  if(key==='/settings/strategy')return '/strategy';
  if(key==='/settings/automation')return '/strategy?tab=automation';
  if(key==='/products-legacy')return '/products';
  if(key==='/orders-legacy')return '/orders';
  if(key==='/chat-legacy')return '/chat';
  return key||'/';
}
