import { useCallback, useEffect, useRef, useState } from 'react';
import type { PointerEvent as ReactPointerEvent } from 'react';
import {
  BookOpen, Compass, PanelLeftClose, PanelLeftOpen, Lightbulb, ListTodo,
  PackagePlus, PenSquare, Settings, Truck, TrendingUp, UserRound, ShoppingBag, Package, Palette, ChevronDown
} from 'lucide-react';
import * as DropdownMenu from '@radix-ui/react-dropdown-menu';
import { IconButton, ToolButton } from './components/ui';
import AppearancePage, { type ThemeMode } from './pages/AppearancePage';
import DesignSystemPage from './pages/DesignSystemPage';
import TodoPage from './pages/TodoPage';
import OverviewPage from './pages/OverviewPage';
import ChatPage from './pages/ChatPage';
import ProductsPage from './pages/ProductsPage';
import OrdersPage from './pages/OrdersPage';
import {readProductChanges,writeProductChanges,type ProductChanges} from './domain/products';
import { countWorkTab, readWorkDecisions, writeWorkDecisions, type WorkDecisions } from './domain/work-items';
import {
  CHAT_CURRENT_KEY, CHAT_MAX_MESSAGES, CHAT_MAX_THREADS, CHAT_STORAGE_KEY,
  makeChatExchange, makeDemoResponse, makeId, readChatThreads, saveChatThreads,
  type ChatAttachment, type ChatThread
} from './domain/chat';
import GrowthPage from './pages/GrowthPage';
import StrategyPage from './pages/StrategyPage';
import KnowledgePage from './pages/KnowledgePage';
import NativeSettingsPage from './pages/NativeSettingsPage';
import NewProductPage from './pages/NewProductPage';
import UtilityPages from './pages/UtilityPages';
import { resolveNativeRoute } from './domain/native-store';
import BusinessAssistant from './components/BusinessAssistant';
import BrandMark from './components/BrandMark';

type NavRoute = { label: string; path: string; icon: typeof Compass; count?: number };
export const QUICK_ROUTES: NavRoute[] = [
  { label: '新对话', path: '/chat', icon: PenSquare },
  { label: '上新', path: '/new-product', icon: PackagePlus },
];
export const MAIN_ROUTES: NavRoute[] = [
  { label: '概览', path: '/', icon: Lightbulb },
  { label: '待办', path: '/todo', icon: ListTodo, count: 2 },
  { label: '订单', path: '/orders?tab=due', icon: Truck, count: 1 },
  { label: '商品', path: '/products', icon: Package },
  { label: '增长', path: '/growth', icon: TrendingUp },
  { label: '经营策略', path: '/strategy', icon: Compass },
  { label: '知识库', path: '/kb', icon: BookOpen },
];
const clamp = (n: number) => Math.max(200, Math.min(440, n));
const routeKey = (p: string) => p.split('?')[0].replace(/\.html$/, '').replace(/^\/index$/, '/') || '/';
const canonicalRoute = (input:string) => {
  const [path,...parts]=input.split('?');
  if(path==='/products' && parts.join('?').includes('intent=create'))return '/new-product';
  const normalized=resolveNativeRoute(path);
  return normalized+(normalized===path&&parts.length?'?'+parts.join('?'):'');
};
function storedValue<T>(key: string, fallback: T, parse: (value: string) => T): T {
  try { const found = localStorage.getItem(key); return found == null ? fallback : parse(found); }
  catch { return fallback; }
}
function startingRoute(): string {
  const path = new URLSearchParams(location.search).get('view');
  if(path?.startsWith('/') && !path.startsWith('//'))return canonicalRoute(path);
  const direct=location.pathname.replace(/\.html$/,'');
  return canonicalRoute(direct==='/'?'/chat':direct+location.search);
}
function NavEntry({ item, current, onNavigate, count, activeOverride }: { item: NavRoute; current: string; onNavigate: (path: string) => void; count?: number; activeOverride?:boolean }) {
  const Icon = item.icon;
  const currentBase = routeKey(current);
  const itemBase = routeKey(item.path);
  const active = activeOverride ?? (currentBase === itemBase || (itemBase !== '/' && currentBase.startsWith(itemBase + '/')));
  return <button className={'nav-entry' + (active ? ' is-active' : '')}
    aria-label={item.label} title={item.label}
    aria-current={active ? 'page' : undefined} onClick={() => onNavigate(item.path)}>
    <Icon size={20} strokeWidth={1.8} className="nav-icon" />
    <span className="nav-label">{item.label}</span>
    {(count ?? item.count) != null && (count ?? item.count)! > 0 &&
      <span className={'nav-counter ' + (item.label === '待办' ? 'error' : 'warning')}>{count ?? item.count}</span>}
  </button>;
}

export default function App() {
  const [route, setRoute] = useState(startingRoute);
  const [width, setWidth] = useState(() => storedValue('orbita-rebuild-width', 260, x => clamp(+x || 260)));
  const [collapsed, setCollapsed] = useState(() => storedValue('orbita-rebuild-collapsed', false, x => x === 'true'));
  const [themeMode, setThemeMode] = useState<ThemeMode>(() =>
    storedValue('orbita-rebuild-theme', 'system' as ThemeMode,
      x => x === 'light' || x === 'dark' ? x : 'system'));
  const [systemDark, setSystemDark] = useState(() => matchMedia('(prefers-color-scheme: dark)').matches);
  const [mobile, setMobile] = useState(false);
  const [workDecisions, setWorkDecisions] = useState<WorkDecisions>(readWorkDecisions);
  const [productChanges,setProductChanges]=useState<ProductChanges>(readProductChanges);
  const [chatThreads, setChatThreads] = useState<ChatThread[]>(readChatThreads);
  const [historyVisible,setHistoryVisible]=useState(true);
  const [currentChatId, setCurrentChatId] = useState<string | null>(()=>
    storedValue<string|null>(CHAT_CURRENT_KEY,null,value=>value||null));
  const [chatReset, setChatReset] = useState(0);
  const [handoffQuestion,setHandoffQuestion]=useState('');
  const [pageScrolled,setPageScrolled]=useState(false);
  const dragRef = useRef<{ x: number; width: number } | null>(null);
  const theme = themeMode === 'system' ? (systemDark ? 'dark' : 'light') : themeMode;
  const isNativeAppearance = routeKey(route) === '/settings/appearance';
  const isDesignSystem = routeKey(route) === '/design-system';
  const isNativeTodo = routeKey(route) === '/todo';
  const isNativeOverview = routeKey(route) === '/';
  const isNativeChat = routeKey(route) === '/chat';
  const isNativeProducts = routeKey(route) === '/products';
  const isNativeOrders=routeKey(route)==='/orders'||routeKey(route)==='/orders/fulfillment';
  const isGrowth=routeKey(route)==='/growth'||routeKey(route)==='/growth/promotions';
  const isStrategy=routeKey(route)==='/strategy'||routeKey(route)==='/settings/automation'||routeKey(route)==='/settings/strategy';
  const isKnowledge=routeKey(route)==='/kb';
  const isNewProduct=routeKey(route)==='/new-product';
  const isNativeSettings=routeKey(route).startsWith('/settings/');
  const isPublicPage=['/site','/site/autopilot','/forgot-password','/reset-password',
    '/legal/privacy','/legal/terms'].includes(routeKey(route));
  const currentChat = chatThreads.find(x=>x.id===currentChatId) || null;

  useEffect(() => {
    const media = matchMedia('(prefers-color-scheme: dark)');
    const onChange = () => setSystemDark(media.matches);
    onChange();
    media.addEventListener('change', onChange);
    return () => media.removeEventListener('change', onChange);
  }, []);
  useEffect(() => {
    function onStorage(e: StorageEvent) {
      if (e.key === 'orbita-rebuild-theme') {
        setThemeMode(e.newValue === 'dark' || e.newValue === 'light' ? e.newValue : 'system');
      }
    }
    window.addEventListener('storage', onStorage);
    return () => window.removeEventListener('storage', onStorage);
  }, []);
  useEffect(() => {
    document.documentElement.dataset.theme = theme;
    localStorage.setItem('orbita-rebuild-theme', themeMode);
  }, [theme, themeMode]);
  useEffect(() => { localStorage.setItem('orbita-rebuild-width', String(width)); }, [width]);
  useEffect(() => { localStorage.setItem('orbita-rebuild-collapsed', String(collapsed)); }, [collapsed]);
  useEffect(() => { writeWorkDecisions(workDecisions); }, [workDecisions]);
  useEffect(()=>{writeProductChanges(productChanges)},[productChanges]);
  useEffect(()=>{
    const fn=(e:StorageEvent)=>{if(e.key==='orbita-rebuild-demo-products-v1')setProductChanges(readProductChanges())};
    window.addEventListener('storage',fn);return()=>window.removeEventListener('storage',fn);
  },[]);
  useEffect(() => { saveChatThreads(chatThreads); }, [chatThreads]);
  useEffect(() => {
    try {localStorage.setItem(CHAT_CURRENT_KEY,currentChatId||'')} catch {/* private browsing */}
  }, [currentChatId]);
  useEffect(() => {
    const onStorage = (e:StorageEvent)=>{
      if(e.key===CHAT_STORAGE_KEY)setChatThreads(readChatThreads());
      if(e.key===CHAT_CURRENT_KEY)setCurrentChatId(e.newValue||null);
    };
    window.addEventListener('storage',onStorage);
    return ()=>window.removeEventListener('storage',onStorage);
  },[]);
  useEffect(() => {
    const onStorage=(e:StorageEvent)=>{if(e.key==='orbita-rebuild-demo-work-v1')setWorkDecisions(readWorkDecisions())};
    window.addEventListener('storage',onStorage);
    return ()=>window.removeEventListener('storage',onStorage);
  },[]);
  const visit = useCallback((next: string, push = true) => {
    const canonical=canonicalRoute(next);
    setRoute(canonical);
    setPageScrolled(false);
    setMobile(false);
    if (push) history.pushState({ view: canonical }, '', '/?view=' + encodeURIComponent(canonical));
  }, []);
  function newChat(){
    setCurrentChatId(null);
    setChatReset(n=>n+1);
    visit('/chat');
  }
  function fullChat(question:string){
    newChat();
    setHandoffQuestion(question);
  }
  useEffect(()=>{if(isNativeChat&&handoffQuestion){sendChatMessage(handoffQuestion,[]);setHandoffQuestion('')}},[isNativeChat,handoffQuestion]);
  function sendChatMessage(text:string,attachments:ChatAttachment[]){
    const textValue=text.trim();
    const exchange=makeChatExchange(textValue,attachments);
    const now=Date.now();
    const newId=currentChat?.id||makeId();
    const title=textValue?textValue.slice(0,30):'附件演示';
    setChatThreads(threads=>{
      const existing=threads.find(t=>t.id===newId);
      const updated:ChatThread={
        id:newId,title:existing?.title||title,updatedAt:now,
        messages:[...(existing?.messages||[]),...exchange].slice(-CHAT_MAX_MESSAGES),
      };
      return [updated,...threads.filter(t=>t.id!==newId)].slice(0,CHAT_MAX_THREADS);
    });
    setCurrentChatId(newId);
  }
  function changeProposal(messageId:string,status:'simulated'|'rejected'){
    if(!currentChatId)return;
    setChatThreads(list=>list.map(thread=>thread.id!==currentChatId?thread:{
      ...thread,messages:thread.messages.map(message=>
        message.id===messageId&&message.proposal?.status==='ready'
          ? {...message,proposal:{...message.proposal,status}} : message),
    }));
  }
  function regenerateChatMessage(messageId:string){
    if(!currentChatId)return;
    setChatThreads(list=>list.map(thread=>{
      if(thread.id!==currentChatId)return thread;
      const index=thread.messages.findIndex(m=>m.id===messageId);
      if(index<0||thread.messages[index].role!=='assistant')return thread;
      const prior=[...thread.messages.slice(0,index)].reverse().find(m=>m.role==='user');
      if(!prior)return thread;
      return {...thread,messages:thread.messages.map(m=>m.id!==messageId?m:{
        ...m,...makeDemoResponse(prior.text,prior.attachments||[]),
      })};
    }));
  }
  useEffect(() => {
    function onPop() { visit(startingRoute(), false); }
    window.addEventListener('popstate', onPop);
    return () => window.removeEventListener('popstate', onPop);
  }, [visit]);
  const beginDrag = (e: ReactPointerEvent<HTMLDivElement>) => {
    if (collapsed || e.button !== 0) return;
    dragRef.current = { x: e.clientX, width };
    e.currentTarget.setPointerCapture(e.pointerId);
    document.body.classList.add('resizing');
  };
  const moveDrag = (e: ReactPointerEvent<HTMLDivElement>) => {
    if (dragRef.current) setWidth(clamp(dragRef.current.width + e.clientX - dragRef.current.x));
  };
  const stopDrag = (e: ReactPointerEvent<HTMLDivElement>) => {
    dragRef.current = null;
    if (e.currentTarget.hasPointerCapture(e.pointerId)) e.currentTarget.releasePointerCapture(e.pointerId);
    document.body.classList.remove('resizing');
  };
  if(isPublicPage)return <div className="app-shell public-shell"><div className="content">
    <UtilityPages route={route} navigate={visit}/>
  </div></div>;
  return <div className="app-shell">
    {mobile && <button className="mobile-overlay" aria-label="关闭侧边栏" onClick={() => setMobile(false)} />}
    <aside className={'sidebar' + (collapsed ? ' is-collapsed' : '') + (mobile ? ' mobile-visible' : '')}
      style={{ width: collapsed ? 'var(--sidebar-rail)' : width }} aria-label="Orbita 导航">
      <div className="sidebar-header">
        {!collapsed&&<span className="brand-icon"><BrandMark/></span>}
        {!collapsed && <span className="brand-name">Orbita</span>}
        <ToolButton label={collapsed ? '展开侧边栏' : '收起侧边栏'} onClick={() => setCollapsed(v => !v)}>
          {collapsed?<PanelLeftOpen size={20} strokeWidth={1.8}/>:<PanelLeftClose size={20} strokeWidth={1.8}/>}
        </ToolButton>
      </div>
      <div className="sidebar-sections">
        <div className="quick-links">{QUICK_ROUTES.map(i => <NavEntry key={i.path} item={i} current={route} activeOverride={i.path==='/chat' ? routeKey(route)==='/chat'&&!currentChatId : undefined}
          onNavigate={i.path==='/chat'?newChat:visit} />)}</div>
        <nav className="main-links" aria-label="功能导航">{MAIN_ROUTES.map(i => <NavEntry key={i.path} item={i} current={route}
          count={i.label==='待办'?countWorkTab('pending',workDecisions):undefined} onNavigate={visit} />)}</nav>
        {!collapsed && <section className="chat-history" aria-label="历史对话">
          <button className="history-toggle" aria-expanded={historyVisible} onClick={()=>setHistoryVisible(v=>!v)}>
            <span>对话</span><ChevronDown aria-hidden="true" className={historyVisible?'':'is-folded'} size={16} strokeWidth={1.8}/>
          </button>
          {historyVisible&&[...chatThreads].sort((a,b)=>b.updatedAt-a.updatedAt).map(thread=><button key={thread.id} title={thread.title}
            className={'history-row'+(routeKey(route)==='/chat'&&thread.id===currentChatId?' is-active':'')}
            aria-current={routeKey(route)==='/chat'&&thread.id===currentChatId?'page':undefined}
            onClick={()=>{setCurrentChatId(thread.id);visit('/chat')}}>{thread.title}</button>)}
          {historyVisible&&!chatThreads.length&&<div className="history-empty">暂无对话</div>}
        </section>}
      </div>
      <footer className="account-footer">
        {!collapsed&&<button className="sidebar-shop" onClick={()=>visit('/settings/shops')} aria-label="查看或连接店铺">
          <span className="sidebar-shop-icon"><ShoppingBag size={19} strokeWidth={1.8}/></span>
          <span className="sidebar-shop-copy"><strong>测试店</strong></span>
        </button>}
        {!collapsed&&<div className="account-separator"/>}
        <div className="account-bottom-row">
        <DropdownMenu.Root>
          <DropdownMenu.Trigger className="account-user" aria-label="打开用户菜单">
            <span className="account-avatar"><UserRound size={24} /></span>
            {!collapsed && <span className="account-details"><strong title="LLYing">LLYing</strong></span>}
          </DropdownMenu.Trigger>
          <DropdownMenu.Portal>
            <DropdownMenu.Content className="account-menu" side="top" align="start" sideOffset={6}>
              <DropdownMenu.Label className="account-menu-title">LLYing</DropdownMenu.Label>
              <DropdownMenu.Item onSelect={() => visit('/settings/account')}><UserRound size={16}/> 我的信息</DropdownMenu.Item>
              <DropdownMenu.Item onSelect={() => visit('/settings/shops')}><ShoppingBag size={16}/> 店铺管理</DropdownMenu.Item>
              <DropdownMenu.Item onSelect={() => visit('/settings/appearance')}><Palette size={16}/> 外观设置</DropdownMenu.Item>
            </DropdownMenu.Content>
          </DropdownMenu.Portal>
        </DropdownMenu.Root>
        {!collapsed && <div className="account-tools">
          <ToolButton label="设置" onClick={() => visit('/settings/account')}><Settings size={20} /></ToolButton>
        </div>}
        </div>
      </footer>
      {!collapsed && <div className="sidebar-resizer" role="separator" aria-label="调整导航宽度"
        tabIndex={0} aria-orientation="vertical" onPointerDown={beginDrag} onPointerMove={moveDrag}
        onPointerUp={stopDrag} onPointerCancel={stopDrag}
        onKeyDown={e => { if (e.key === 'ArrowLeft' || e.key === 'ArrowRight') {
          e.preventDefault(); setWidth(x => clamp(x + (e.key === 'ArrowRight' ? 16 : -16)));
        } }} />}
    </aside>
    <div className={'content'+(pageScrolled?' page-scrolled':'')} onScrollCapture={e=>{
      if(e.target instanceof HTMLElement && e.target.matches('main'))setPageScrolled(e.target.scrollTop>12);
    }}>
      <div className="mobile-header"><IconButton aria-label="打开侧边栏" onClick={() => setMobile(true)}><PanelLeftOpen size={20} /></IconButton> Orbita</div>
      {isNativeAppearance
        ? <AppearancePage mode={themeMode} resolvedTheme={theme}
            onModeChange={setThemeMode} navigate={visit}/>
        : isDesignSystem
        ? <DesignSystemPage navigate={visit}/>
        : isNativeTodo
        ? <TodoPage navigate={visit} decisions={workDecisions} setDecisions={setWorkDecisions}/>
        : isNativeOverview
        ? <OverviewPage navigate={visit} decisions={workDecisions} productChanges={productChanges}/>
        : isNativeChat
        ? <ChatPage key={currentChatId||'new-'+chatReset} thread={currentChat} onNew={newChat} onSend={sendChatMessage}
            onDecide={changeProposal} onRegenerate={regenerateChatMessage}
            navigate={visit} workDecisions={workDecisions}/>
        : isNativeProducts
        ? <ProductsPage navigate={visit} changes={productChanges} setChanges={setProductChanges}/>
        : isNativeOrders
        ? <OrdersPage key={routeKey(route)} navigate={visit} route={route}/>
        : isGrowth
        ? <GrowthPage navigate={visit} route={route} products={productChanges} decisions={workDecisions}/>
        : isStrategy
        ? <StrategyPage navigate={visit} route={route}/>
        : isKnowledge
        ? <KnowledgePage navigate={visit}/>
        : isNewProduct
        ? <NewProductPage navigate={visit}/>
        : isNativeSettings
        ? <NativeSettingsPage route={route} navigate={visit}/>
        : <UtilityPages route={route} navigate={visit}/>}
      {!isNativeChat&&!isNativeAppearance&&!isDesignSystem&&!isNativeSettings&&!isKnowledge&&!isPublicPage&&routeKey(route)!=='/more'&&
        <BusinessAssistant route={route} onFullChat={fullChat}/>}
    </div>
  </div>;
}
